"use strict";
/* ================= SCORES AND CALCULATORS (declarative) ================= */
const TOOLS=[{"id": "heart", "name": "HEART score", "kind": "score", "group": "Cardiac", "use": "Risk-stratify undifferentiated chest pain in the emergency department for 6-week major adverse cardiac events (MACE).", "items": [{"k": "hx", "label": "History", "opts": [["Slightly suspicious", 0], ["Moderately suspicious", 1], ["Highly suspicious", 2]]}, {"k": "ecg", "label": "ECG", "opts": [["Normal", 0], ["Non-specific repolarisation disturbance (LBBB, LVH, digoxin, no significant ST deviation)", 1], ["Significant ST deviation (not due to BBB, LVH or digoxin)", 2]]}, {"k": "age", "label": "Age", "opts": [["< 45 years", 0], ["45–64 years", 1], ["≥ 65 years", 2]]}, {"k": "rf", "label": "Risk factors (HTN, hypercholesterolaemia, DM, obesity BMI > 30, smoking, family history, or known atherosclerotic disease)", "opts": [["No known risk factors", 0], ["1–2 risk factors", 1], ["≥ 3 risk factors, or history of atherosclerotic disease (MI, PCI, CABG, stroke, PAD)", 2]]}, {"k": "trop", "label": "Initial troponin", "opts": [["≤ normal limit (99th centile)", 0], ["1–3 × normal limit", 1], ["> 3 × normal limit", 2]]}], "bands": [{"min": 0, "max": 3, "label": "Low", "text": "0.9–1.7% MACE at 6 weeks. Suitable for early discharge with outpatient follow-up, provided serial troponins are negative (HEART Pathway)."}, {"min": 4, "max": 6, "label": "Moderate", "text": "12–16.6% MACE at 6 weeks. Admit for observation, serial troponins and objective testing."}, {"min": 7, "max": 10, "label": "High", "text": "50–65% MACE at 6 weeks. Early invasive strategy; cardiology referral."}], "src": "Six AJ et al. Neth Heart J 2008; Backus BE et al. Int J Cardiol 2013 (validation); Mahler SA et al. HEART Pathway, Circ Cardiovasc Qual Outcomes 2015", "note": "Use with a high-sensitivity troponin assay and at least one repeat troponin (HEART Pathway). Not for STEMI, haemodynamic instability or a clear non-cardiac cause. The 'history' item is subjective and is the main source of inter-rater variability."}, {"id": "wells-pe", "name": "Wells score for pulmonary embolism", "kind": "score", "group": "Respiratory", "use": "Estimate pre-test probability of PE to decide between D-dimer testing and direct imaging (CTPA).", "items": [{"k": "dvt", "label": "Clinical signs and symptoms of DVT (leg swelling, pain with palpation of deep veins)", "opts": [["No", 0], ["Yes", 3]]}, {"k": "alt", "label": "PE is the most likely diagnosis (no better alternative)", "opts": [["No", 0], ["Yes", 3]]}, {"k": "hr", "label": "Heart rate > 100 /min", "opts": [["No", 0], ["Yes", 1.5]]}, {"k": "immob", "label": "Immobilisation ≥ 3 days or surgery in the previous 4 weeks", "opts": [["No", 0], ["Yes", 1.5]]}, {"k": "prev", "label": "Previous objectively diagnosed DVT or PE", "opts": [["No", 0], ["Yes", 1.5]]}, {"k": "haem", "label": "Haemoptysis", "opts": [["No", 0], ["Yes", 1]]}, {"k": "ca", "label": "Malignancy (on treatment, treated within 6 months, or palliative)", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 1.5, "label": "Low (three-tier) · PE unlikely (two-tier)", "text": "Three-tier: low probability (~1.3% PE). Two-tier (≤ 4): PE unlikely — D-dimer; if negative, PE excluded without imaging (NICE NG158)."}, {"min": 2, "max": 4, "label": "Moderate (three-tier) · PE unlikely (two-tier)", "text": "Three-tier: moderate probability (~16% PE). Two-tier (≤ 4): PE unlikely — D-dimer (consider age-adjusted threshold); if negative, PE excluded; if positive, CTPA."}, {"min": 4.5, "max": 6, "label": "Moderate (three-tier) · PE likely (two-tier)", "text": "Three-tier: moderate probability (~16% PE). Two-tier (> 4): PE likely — go straight to CTPA (or V/Q); do not rely on D-dimer. Consider interim anticoagulation if imaging is delayed."}, {"min": 6.5, "max": 12.5, "label": "High (three-tier) · PE likely (two-tier)", "text": "Three-tier: high probability (~37.5% PE). Two-tier: PE likely — immediate CTPA; start anticoagulation if imaging will be delayed and bleeding risk permits."}], "src": "Wells PS et al. Thromb Haemost 2000 (three-tier: < 2 low, 2–6 moderate, > 6 high); Wells PS et al. Ann Intern Med 2001 (two-tier: ≤ 4 unlikely, > 4 likely); NICE NG158 2020 (uses two-tier)", "note": "NICE NG158 uses the two-tier version. 'PE most likely' is a subjective item that carries 3 points and drives the score. Apply PERC first in low-risk patients; the YEARS algorithm is an alternative that reduces imaging. In pregnancy neither Wells nor D-dimer is validated — follow RCOG."}, {"id": "perc", "name": "PERC rule (Pulmonary Embolism Rule-out Criteria)", "kind": "score", "group": "Respiratory", "use": "In a patient with LOW clinical suspicion of PE (gestalt < 15%), rule out PE without D-dimer when all eight criteria are negative.", "items": [{"k": "age", "label": "Age ≥ 50 years", "opts": [["No", 0], ["Yes", 1]]}, {"k": "hr", "label": "Heart rate ≥ 100 /min", "opts": [["No", 0], ["Yes", 1]]}, {"k": "spo2", "label": "SpO₂ < 95% on room air", "opts": [["No", 0], ["Yes", 1]]}, {"k": "haem", "label": "Haemoptysis", "opts": [["No", 0], ["Yes", 1]]}, {"k": "oest", "label": "Exogenous oestrogen (OCP, HRT)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "prev", "label": "Previous DVT or PE", "opts": [["No", 0], ["Yes", 1]]}, {"k": "leg", "label": "Unilateral leg swelling", "opts": [["No", 0], ["Yes", 1]]}, {"k": "surg", "label": "Surgery or trauma requiring hospitalisation within the previous 4 weeks", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "PERC negative", "text": "All criteria negative in a low-pretest-probability patient: PE can be ruled out without D-dimer (< 2% miss rate; PROPER trial 2018 confirmed safety)."}, {"min": 1, "max": 8, "label": "PERC positive — cannot rule out", "text": "Any criterion present: PERC cannot exclude PE. Proceed to Wells/YEARS and D-dimer or imaging as indicated."}], "src": "Kline JA et al. J Thromb Haemost 2004; Kline JA et al. J Thromb Haemost 2008 (validation); Freund Y et al. PROPER, JAMA 2018", "note": "Only valid when the clinician's pre-test probability is low (< 15%, e.g. Wells low or gestalt low). It is a rule-out checklist, not a probability score. Not validated in pregnancy."}, {"id": "years", "name": "YEARS algorithm", "kind": "score", "group": "Respiratory", "use": "Simplified PE work-up: three items plus a D-dimer threshold that depends on the item count; reduces CTPA use compared with Wells.", "items": [{"k": "dvt", "label": "Clinical signs of DVT", "opts": [["No", 0], ["Yes", 1]]}, {"k": "haem", "label": "Haemoptysis", "opts": [["No", 0], ["Yes", 1]]}, {"k": "alt", "label": "PE is the most likely diagnosis", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "No YEARS items", "text": "D-dimer threshold 1000 µg/L FEU (1000 ng/mL). D-dimer < 1000 → PE excluded, no imaging. D-dimer ≥ 1000 → CTPA."}, {"min": 1, "max": 3, "label": "≥ 1 YEARS item", "text": "D-dimer threshold 500 µg/L FEU (500 ng/mL). D-dimer < 500 → PE excluded, no imaging. D-dimer ≥ 500 → CTPA."}], "src": "van der Hulle T et al. Lancet 2017 (YEARS study); Pregnancy-adapted YEARS: van der Pol LM et al. NEJM 2019", "note": "D-dimer is measured in everyone at the outset. 3-month VTE failure rate 0.61% in untreated patients. Pregnancy-adapted YEARS adds compression ultrasound when DVT signs are present. Not for haemodynamically unstable patients or those already anticoagulated."}, {"id": "wells-dvt", "name": "Wells score for DVT", "kind": "score", "group": "Cardiac", "use": "Estimate pre-test probability of lower-limb DVT to decide between D-dimer and proximal-leg vein ultrasound.", "items": [{"k": "ca", "label": "Active cancer (treatment ongoing, within 6 months, or palliative)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "par", "label": "Paralysis, paresis or recent plaster immobilisation of the lower limb", "opts": [["No", 0], ["Yes", 1]]}, {"k": "bed", "label": "Recently bedridden ≥ 3 days, or major surgery within 12 weeks requiring general/regional anaesthesia", "opts": [["No", 0], ["Yes", 1]]}, {"k": "tend", "label": "Localised tenderness along the distribution of the deep venous system", "opts": [["No", 0], ["Yes", 1]]}, {"k": "leg", "label": "Entire leg swollen", "opts": [["No", 0], ["Yes", 1]]}, {"k": "calf", "label": "Calf swelling ≥ 3 cm compared with the asymptomatic leg (measured 10 cm below tibial tuberosity)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "oed", "label": "Pitting oedema confined to the symptomatic leg", "opts": [["No", 0], ["Yes", 1]]}, {"k": "coll", "label": "Collateral superficial veins (non-varicose)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "prev", "label": "Previously documented DVT", "opts": [["No", 0], ["Yes", 1]]}, {"k": "alt", "label": "Alternative diagnosis at least as likely as DVT", "opts": [["No", 0], ["Yes", -2]]}], "bands": [{"min": -2, "max": 0, "label": "Low (three-tier) · DVT unlikely (two-tier)", "text": "Three-tier: low (~5% DVT). Two-tier (≤ 1): DVT unlikely — D-dimer; negative D-dimer excludes DVT; positive → proximal leg vein ultrasound within 4 h (NICE NG158)."}, {"min": 1, "max": 1, "label": "Moderate (three-tier) · DVT unlikely (two-tier)", "text": "Three-tier: moderate (~17% DVT). Two-tier (≤ 1): DVT unlikely — D-dimer first; ultrasound only if positive."}, {"min": 2, "max": 2, "label": "Moderate (three-tier) · DVT likely (two-tier)", "text": "Three-tier: moderate (~17% DVT). Two-tier (≥ 2): DVT likely — proximal leg vein ultrasound within 4 h; if not available, D-dimer, interim anticoagulation and scan within 24 h."}, {"min": 3, "max": 9, "label": "High (three-tier) · DVT likely (two-tier)", "text": "Three-tier: high (~53% DVT). Two-tier: DVT likely — ultrasound within 4 h (or D-dimer plus interim anticoagulation and scan within 24 h). If the first scan is negative but D-dimer positive, repeat scan in 6–8 days."}], "src": "Wells PS et al. Lancet 1997 (three-tier: ≤ 0 low, 1–2 moderate, ≥ 3 high); Wells PS et al. NEJM 2003 (modified, adds previous DVT; two-tier: ≤ 1 unlikely, ≥ 2 likely); NICE NG158 2020", "note": "NICE NG158 uses the two-tier modified (2003) version. Less reliable in pregnancy, prior DVT in the same leg, or anticoagulated patients; in pregnancy go straight to ultrasound."}, {"id": "curb65", "name": "CURB-65", "kind": "score", "group": "Respiratory", "use": "Severity and 30-day mortality of community-acquired pneumonia in hospital, to guide admission and treatment setting.", "items": [{"k": "c", "label": "Confusion (new disorientation in person, place or time, or AMTS ≤ 8/10)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "u", "label": "Urea > 7 mmol/L", "opts": [["No", 0], ["Yes", 1]]}, {"k": "r", "label": "Respiratory rate ≥ 30 /min", "opts": [["No", 0], ["Yes", 1]]}, {"k": "b", "label": "Blood pressure: systolic < 90 mmHg or diastolic ≤ 60 mmHg", "opts": [["No", 0], ["Yes", 1]]}, {"k": "a", "label": "Age ≥ 65 years", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 1, "label": "Low severity", "text": "30-day mortality < 3% (0: 0.7%, 1: 2.1%). Consider home-based care (score 0–1) if social circumstances allow."}, {"min": 2, "max": 2, "label": "Intermediate severity", "text": "30-day mortality ~9%. Consider hospital-supervised treatment (short admission or hospital-supervised outpatient care)."}, {"min": 3, "max": 5, "label": "High severity", "text": "30-day mortality 15–40% (3: 14%, 4: 40%, 5: 57%). Urgent admission; score 4–5 — assess for critical care (ICU/HDU)."}], "src": "Lim WS et al. Thorax 2003; BTS CAP guideline 2009 (2015 annotated); NICE CG191 2014 (updated 2023)", "note": "For hospital assessment; in primary care use CRB-65 (no urea): 0 low, 1–2 intermediate, 3–4 high. Clinical judgement overrides — hypoxaemia, bilateral/multilobar changes and comorbidity are not scored. Underestimates severity in the young."}, {"id": "qsofa", "name": "qSOFA", "kind": "score", "group": "Infection", "use": "Bedside prompt for poor outcome in suspected infection outside the ICU (Sepsis-3); not a diagnostic or screening tool for sepsis.", "items": [{"k": "rr", "label": "Respiratory rate ≥ 22 /min", "opts": [["No", 0], ["Yes", 1]]}, {"k": "ams", "label": "Altered mentation (GCS < 15)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "sbp", "label": "Systolic BP ≤ 100 mmHg", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 1, "label": "qSOFA negative", "text": "Lower risk, but does NOT exclude sepsis (sensitivity ~50–60%). Continue to assess with NEWS2 and clinical judgement; reassess if deteriorating."}, {"min": 2, "max": 3, "label": "qSOFA positive", "text": "Higher risk of in-hospital mortality (~10% or more) and prolonged ICU stay. Assess for organ dysfunction (full SOFA), lactate, cultures, antibiotics within 1 h, senior review."}], "src": "Singer M et al. Sepsis-3, JAMA 2016; Seymour CW et al. JAMA 2016; Surviving Sepsis Campaign 2021", "note": "Surviving Sepsis Campaign 2021 recommends AGAINST using qSOFA as a single screening tool (compared with SIRS, NEWS or MEWS) because of poor sensitivity. UK practice (NICE NG51, RCP) uses NEWS2 ≥ 5 as the sepsis trigger."}, {"id": "news2", "name": "NEWS2 (National Early Warning Score 2)", "kind": "score", "group": "General", "use": "Standardised assessment of acute-illness severity and deterioration in adults (≥ 16 years, not pregnant) in hospital and pre-hospital settings.", "items": [{"k": "rr", "label": "Respiratory rate (/min)", "opts": [["≤ 8", 3], ["9–11", 1], ["12–20", 0], ["21–24", 2], ["≥ 25", 3]]}, {"k": "spo2a", "label": "SpO₂ Scale 1 (use for all patients unless Scale 2 is prescribed)", "opts": [["Using Scale 2 instead (score 0 here)", 0], ["≤ 91%", 3], ["92–93%", 2], ["94–95%", 1], ["≥ 96%", 0]]}, {"k": "spo2b", "label": "SpO₂ Scale 2 (ONLY if a clinician has set a target of 88–92%, e.g. hypercapnic COPD)", "opts": [["Not using Scale 2 (score 0 here)", 0], ["≤ 83%", 3], ["84–85%", 2], ["86–87%", 1], ["88–92%, or ≥ 93% on air", 0], ["93–94% on oxygen", 1], ["95–96% on oxygen", 2], ["≥ 97% on oxygen", 3]]}, {"k": "o2", "label": "Air or supplemental oxygen", "opts": [["Air", 0], ["Any supplemental oxygen", 2]]}, {"k": "sbp", "label": "Systolic BP (mmHg)", "opts": [["≤ 90", 3], ["91–100", 2], ["101–110", 1], ["111–219", 0], ["≥ 220", 3]]}, {"k": "hr", "label": "Pulse (/min)", "opts": [["≤ 40", 3], ["41–50", 1], ["51–90", 0], ["91–110", 1], ["111–130", 2], ["≥ 131", 3]]}, {"k": "acvpu", "label": "Consciousness (ACVPU)", "opts": [["Alert", 0], ["New Confusion, Voice, Pain or Unresponsive", 3]]}, {"k": "temp", "label": "Temperature (°C)", "opts": [["≤ 35.0", 3], ["35.1–36.0", 1], ["36.1–38.0", 0], ["38.1–39.0", 1], ["≥ 39.1", 2]]}], "bands": [{"min": 0, "max": 0, "label": "Low", "text": "Routine monitoring: observations at least every 12 h."}, {"min": 1, "max": 4, "label": "Low (ward-based response)", "text": "Observations at least every 4–6 h; registered nurse to decide on escalation. IMPORTANT: if any SINGLE parameter scores 3 the risk is low–medium — urgent review by a ward-based doctor (observations at least hourly)."}, {"min": 5, "max": 6, "label": "Medium — key threshold", "text": "Urgent response: observations at least hourly; urgent review by a clinician with competencies in acute illness (consider critical-care outreach). Score ≥ 5 is the trigger to screen for sepsis in the presence of infection."}, {"min": 7, "max": 23, "label": "High", "text": "Emergency response: continuous monitoring; immediate review by a team with critical-care competencies, usually in a level 2/3 bed."}], "src": "Royal College of Physicians. National Early Warning Score (NEWS) 2: Standardising the assessment of acute-illness severity in the NHS. RCP, December 2017", "note": "Score only one SpO₂ scale (leave the other at 0). Scale 2 must be a documented clinical decision for hypercapnic respiratory failure. 'New confusion' scores 3 only if new or worse than baseline. Not validated in pregnancy (use MEOWS) or under 16 (use PEWS). The single-parameter-3 trigger cannot be computed from the total alone — the app should flag it."}, {"id": "gcs", "name": "Glasgow Coma Scale", "kind": "score", "group": "Neuro", "use": "Standardised assessment of level of consciousness after head injury or in any reduced-consciousness state; report the three components as well as the total (e.g. E3 V4 M5 = 12).", "items": [{"k": "e", "label": "Eye opening (E)", "opts": [["None — no opening at any time, no interfering factor (E1)", 1], ["To pressure — after fingertip stimulus (E2)", 2], ["To sound — after spoken or shouted request (E3)", 3], ["Spontaneous — open before stimulus (E4)", 4]]}, {"k": "v", "label": "Verbal response (V)", "opts": [["None — no audible response, no interfering factor (V1)", 1], ["Sounds — only moans or groans (V2)", 2], ["Words — intelligible single words, not a coherent exchange (V3)", 3], ["Confused — coherent sentences but not orientated to name, place or date (V4)", 4], ["Orientated — correctly gives name, place and date (V5)", 5]]}, {"k": "m", "label": "Motor response (M)", "opts": [["None — no movement in arms or legs, no interfering factor (M1)", 1], ["Extension — extends arm at elbow to pressure (decerebrate) (M2)", 2], ["Abnormal flexion — bends arm at elbow, clearly abnormal features (decorticate) (M3)", 3], ["Normal flexion — bends arm at elbow rapidly, not abnormal (M4)", 4], ["Localising — brings hand above clavicle to stimulus at head/neck (M5)", 5], ["Obeys commands — two-part request (M6)", 6]]}], "bands": [{"min": 3, "max": 8, "label": "Severe (coma)", "text": "GCS ≤ 8: unable to protect airway — consider definitive airway (intubation); urgent CT head within 1 h after head injury; neurosurgical discussion."}, {"min": 9, "max": 12, "label": "Moderate", "text": "Moderate head injury if trauma-related. CT head within 1 h (GCS < 13 on initial assessment, NICE NG232); close monitoring, repeat GCS every 30 min until 15."}, {"min": 13, "max": 15, "label": "Mild", "text": "Mild head injury if trauma-related. GCS < 15 at 2 h after injury is a high-risk feature (Canadian CT Head Rule / NICE NG232: CT within 1 h)."}], "src": "Teasdale G, Jennett B. Lancet 1974; Teasdale G et al. Lancet Neurol 2014 (40-year update; 'pressure', 'sound' terminology); glasgowcomascale.org", "note": "Record the best response for each component and state 'NT' (not testable) with the reason (e.g. intubated: V-NT, swollen eyes: E-NT) rather than scoring 1. Stimulus: fingertip pressure, trapezius pinch, supraorbital notch. Use the paediatric GCS under 2–5 years. A total of 3 is the minimum."}, {"id": "cchr", "name": "Canadian CT Head Rule", "kind": "score", "group": "Trauma", "use": "Decide which adults with MINOR head injury (GCS 13–15 with witnessed loss of consciousness, definite amnesia or witnessed disorientation) need a CT head.", "items": [{"k": "gcs", "label": "HIGH RISK: GCS < 15 at 2 hours after injury", "opts": [["No", 0], ["Yes", 10]]}, {"k": "open", "label": "HIGH RISK: Suspected open or depressed skull fracture", "opts": [["No", 0], ["Yes", 10]]}, {"k": "basal", "label": "HIGH RISK: Any sign of basal skull fracture (haemotympanum, 'racoon' eyes, CSF oto/rhinorrhoea, Battle's sign)", "opts": [["No", 0], ["Yes", 10]]}, {"k": "vom", "label": "HIGH RISK: ≥ 2 episodes of vomiting", "opts": [["No", 0], ["Yes", 10]]}, {"k": "age", "label": "HIGH RISK: Age ≥ 65 years", "opts": [["No", 0], ["Yes", 10]]}, {"k": "amn", "label": "MEDIUM RISK: Amnesia before impact ≥ 30 minutes (retrograde)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "mech", "label": "MEDIUM RISK: Dangerous mechanism (pedestrian struck by vehicle, occupant ejected from vehicle, fall from > 3 feet / 1 m or > 5 stairs)", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "No CT required", "text": "No high- or medium-risk features: CT not indicated by the rule (sensitivity 100% for neurosurgical intervention, 98.4% for clinically important brain injury). Discharge with written head-injury advice if otherwise well."}, {"min": 1, "max": 9, "label": "Medium risk — CT recommended", "text": "Medium-risk feature(s) present: risk of clinically important brain injury on CT (~1–3%). CT head recommended (the rule's medium-risk tier identifies brain injury on CT, not just neurosurgical need)."}, {"min": 10, "max": 70, "label": "High risk — CT required", "text": "High-risk feature(s) present: risk of needing neurosurgical intervention. CT head required (NICE NG232: within 1 hour)."}], "src": "Stiell IG et al. The Canadian CT Head Rule for patients with minor head injury. Lancet 2001; validation Stiell IG et al. JAMA 2005", "note": "Apply ONLY if: age ≥ 16, GCS 13–15, injury within 24 h, and LOC/amnesia/disorientation witnessed or definite. EXCLUDE (CT or judgement outside the rule): minimal head injury without LOC/amnesia/disorientation, obvious penetrating or depressed fracture, acute focal neurological deficit, unstable vital signs, seizure before assessment, bleeding disorder or oral anticoagulant use, return visit for same injury, pregnancy. UK practice follows NICE NG232 (2023), whose criteria overlap but differ (e.g. anticoagulation, any post-traumatic seizure, > 1 vomiting episode, and 1-hour vs 8-hour CT windows)."}, {"id": "ccsr", "name": "Canadian C-spine Rule", "kind": "score", "group": "Trauma", "use": "Decide whether an alert (GCS 15), stable adult trauma patient with neck pain or concern for C-spine injury needs cervical spine imaging — three sequential steps.", "items": [{"k": "high", "label": "STEP 1 — Any HIGH-RISK factor? Age ≥ 65; dangerous mechanism (fall ≥ 1 m / 5 stairs, axial load to head e.g. diving, high-speed MVC > 100 km/h, rollover or ejection, motorised recreational vehicle, bicycle collision); paraesthesia in extremities", "opts": [["No high-risk factor", 0], ["Yes — high-risk factor present", 100]]}, {"k": "low", "label": "STEP 2 — Any LOW-RISK factor that allows safe assessment of range of movement? Simple rear-end MVC (not pushed into traffic, not hit by bus/large truck, no rollover, not hit by high-speed vehicle); sitting position in ED; ambulatory at any time since injury; delayed (not immediate) onset of neck pain; absence of midline C-spine tenderness", "opts": [["Yes — at least one low-risk factor present", 0], ["No low-risk factor", 10]]}, {"k": "rot", "label": "STEP 3 — Able to ACTIVELY rotate the neck 45° to the left AND right (regardless of pain)?", "opts": [["Yes — rotates 45° both ways", 0], ["No — unable", 1]]}], "bands": [{"min": 0, "max": 0, "label": "No imaging required", "text": "No high-risk factor, a low-risk factor permits assessment, and active rotation 45° each way achieved: C-spine can be cleared clinically without imaging (sensitivity 99.4–100%)."}, {"min": 1, "max": 9, "label": "Imaging required — unable to rotate", "text": "Low-risk factor present but patient cannot actively rotate 45° both ways: imaging required (CT per NICE NG232 in adults; X-ray acceptable in low-risk young patients)."}, {"min": 10, "max": 99, "label": "Imaging required — no low-risk factor", "text": "No low-risk factor to allow safe range-of-movement assessment: imaging required. Do not test rotation."}, {"min": 100, "max": 111, "label": "Imaging required — high-risk factor", "text": "High-risk factor present: imaging required (CT cervical spine). Maintain immobilisation."}], "src": "Stiell IG et al. The Canadian C-Spine Rule for radiography in alert and stable trauma patients. JAMA 2001; validation vs NEXUS: Stiell IG et al. NEJM 2003; NICE NG232 2023", "note": "Apply only to: age ≥ 16, alert (GCS 15), stable vitals, acute blunt trauma. Do NOT apply to: penetrating trauma, acute paralysis, known vertebral disease (ankylosing spondylitis, RA, spinal stenosis, previous C-spine surgery), pregnancy, or presentation > 48 h. More sensitive and specific than NEXUS in head-to-head comparison. The weighted points here encode the three steps; the total has no meaning beyond the band."}, {"id": "nexus", "name": "NEXUS criteria (C-spine)", "kind": "score", "group": "Trauma", "use": "Clinically clear the cervical spine in blunt trauma without imaging when all five low-risk criteria are met.", "items": [{"k": "tend", "label": "Posterior midline cervical tenderness", "opts": [["Absent", 0], ["Present", 1]]}, {"k": "neuro", "label": "Focal neurological deficit", "opts": [["Absent", 0], ["Present", 1]]}, {"k": "alert", "label": "Altered level of alertness (GCS < 15, disorientation, delayed response, agitation)", "opts": [["Normal alertness", 0], ["Altered", 1]]}, {"k": "intox", "label": "Evidence of intoxication", "opts": [["No", 0], ["Yes", 1]]}, {"k": "distract", "label": "Painful distracting injury (e.g. long-bone fracture, large burn, visceral injury)", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "NEXUS negative — no imaging", "text": "All five criteria met: cervical spine can be cleared clinically (sensitivity 99.6% for clinically significant injury; specificity only 12.9%)."}, {"min": 1, "max": 5, "label": "NEXUS positive — image", "text": "One or more criteria not met: cervical spine imaging required (CT preferred in adults per NICE NG232; X-ray series acceptable in selected low-risk/young patients)."}], "src": "Hoffman JR et al. NEXUS. NEJM 2000", "note": "Less specific than the Canadian C-spine Rule and less reliable in patients > 65 years (sensitivity falls). Not validated in children < 8 years for all criteria. Any doubt about a criterion = image."}, {"id": "ottawa-ankle", "name": "Ottawa ankle and foot rules", "kind": "score", "group": "MSK", "use": "Decide whether an acute ankle or midfoot injury needs radiography; sensitivity ~98–100% for clinically significant fracture.", "items": [{"k": "ankzone", "label": "ANKLE SERIES: pain in the malleolar zone AND any of: bone tenderness at the posterior edge or tip of the distal 6 cm of the lateral malleolus; bone tenderness at the posterior edge or tip of the distal 6 cm of the medial malleolus; inability to bear weight (4 steps) both immediately after injury and in the ED", "opts": [["No", 0], ["Yes", 1]]}, {"k": "footzone", "label": "FOOT SERIES: pain in the midfoot zone AND any of: bone tenderness at the base of the 5th metatarsal; bone tenderness at the navicular; inability to bear weight (4 steps) both immediately after injury and in the ED", "opts": [["No", 0], ["Yes", 2]]}], "bands": [{"min": 0, "max": 0, "label": "No X-ray indicated", "text": "Neither rule positive: fracture very unlikely (rule sensitivity 97.6–99.6%). Treat as soft-tissue injury; advise return if unable to bear weight after 5–7 days."}, {"min": 1, "max": 1, "label": "Ankle X-ray series", "text": "Ottawa ankle rule positive: request ankle X-ray (AP, lateral, mortise)."}, {"min": 2, "max": 2, "label": "Foot X-ray series", "text": "Ottawa foot rule positive: request foot X-ray (AP, lateral, oblique)."}, {"min": 3, "max": 3, "label": "Ankle and foot X-ray series", "text": "Both rules positive: request both ankle and foot series."}], "src": "Stiell IG et al. Ann Emerg Med 1992 (derivation); Stiell IG et al. JAMA 1993 (refinement/validation); Bachmann LM et al. BMJ 2003 (meta-analysis, sensitivity 97.6%)", "note": "'Bear weight' = able to transfer weight twice onto each foot (4 steps), limping allowed. Palpate the posterior edge, not the anterior, of each malleolus. Rule is less reliable with: intoxication, altered consciousness, other distracting painful injuries, diminished leg sensation, gross swelling preventing palpation, pregnancy, presentation > 10 days. Validated in children > 5 years (Bachmann 2003; Dowling 2009)."}, {"id": "ottawa-knee", "name": "Ottawa knee rule", "kind": "score", "group": "MSK", "use": "Decide whether an acute knee injury in an adult needs radiography; any one criterion positive → X-ray.", "items": [{"k": "age", "label": "Age ≥ 55 years", "opts": [["No", 0], ["Yes", 1]]}, {"k": "pat", "label": "Isolated tenderness of the patella (no bone tenderness of the knee other than the patella)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "fib", "label": "Tenderness at the head of the fibula", "opts": [["No", 0], ["Yes", 1]]}, {"k": "flex", "label": "Inability to flex the knee to 90°", "opts": [["No", 0], ["Yes", 1]]}, {"k": "wb", "label": "Inability to bear weight (4 steps) both immediately after injury and in the ED", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "No X-ray indicated", "text": "No criteria met: fracture very unlikely (sensitivity ~98.5–100%). Treat as soft-tissue injury; review if not improving."}, {"min": 1, "max": 5, "label": "Knee X-ray indicated", "text": "One or more criteria met: knee X-ray series (AP and lateral)."}], "src": "Stiell IG et al. Ann Emerg Med 1995 (derivation); Stiell IG et al. JAMA 1996 (validation); Bachmann LM et al. Ann Intern Med 2004 (meta-analysis, sensitivity 98.5%)", "note": "Derived in adults ≥ 18 years with acute blunt knee injury within 7 days; also validated in children ≥ 2 years (Bulloch 2003) but not for young children. Not applicable to: isolated skin injuries, injuries > 7 days old, re-evaluation of the same injury, altered consciousness, paraplegia or multiple injuries."}, {"id": "pittsburgh-knee", "name": "Pittsburgh knee rule", "kind": "score", "group": "MSK", "use": "Alternative to the Ottawa knee rule for acute knee injury with a blunt-trauma or fall mechanism; X-ray if the mechanism applies AND age < 12 or > 50, OR unable to walk four weight-bearing steps.", "items": [{"k": "mech", "label": "Mechanism: blunt trauma or a fall (if NO, the rule does not apply — use clinical judgement)", "opts": [["No", 0], ["Yes", 10]]}, {"k": "age", "label": "Age < 12 or > 50 years", "opts": [["No", 0], ["Yes", 1]]}, {"k": "walk", "label": "Unable to walk four weight-bearing steps in the ED", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 9, "label": "Rule does not apply", "text": "The mechanism was not blunt trauma or a fall, so the Pittsburgh rule cannot be used: decide on clinical grounds or apply the Ottawa knee rule."}, {"min": 10, "max": 10, "label": "No X-ray indicated", "text": "Mechanism applies but neither criterion is met: fracture very unlikely (rule sensitivity ≈ 99%, specificity ≈ 60%)."}, {"min": 11, "max": 12, "label": "Knee X-ray indicated", "text": "Mechanism applies and age < 12 or > 50, or unable to take four weight-bearing steps: request a knee X-ray series."}], "src": "Seaberg DC, Jackson R. Am J Emerg Med 1994 (derivation); Seaberg DC et al. Ann Emerg Med 1998 (prospective comparison with Ottawa: sensitivity 99%, specificity 60%)", "note": "More specific than the Ottawa knee rule (60% vs 49%) with similar sensitivity, and includes children. Not applicable to injuries > 6 days old, isolated superficial lacerations/abrasions, previous surgery or fracture of the same knee, or reassessment of the same injury."}, {"id": "alvarado", "name": "Alvarado score (MANTRELS)", "kind": "score", "group": "Abdominal", "use": "Estimate the probability of acute appendicitis in patients with right iliac fossa pain to guide observation versus imaging/surgical referral.", "items": [{"k": "m", "label": "Migration of pain to the right iliac fossa", "opts": [["No", 0], ["Yes", 1]]}, {"k": "a", "label": "Anorexia (or ketones in urine)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "n", "label": "Nausea or vomiting", "opts": [["No", 0], ["Yes", 1]]}, {"k": "t", "label": "Tenderness in the right iliac fossa", "opts": [["No", 0], ["Yes", 2]]}, {"k": "r", "label": "Rebound tenderness", "opts": [["No", 0], ["Yes", 1]]}, {"k": "e", "label": "Elevated temperature ≥ 37.3 °C", "opts": [["No", 0], ["Yes", 1]]}, {"k": "l", "label": "Leukocytosis > 10 × 10⁹/L", "opts": [["No", 0], ["Yes", 2]]}, {"k": "s", "label": "Shift to the left (neutrophils > 75%)", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 4, "label": "Appendicitis unlikely", "text": "Low probability (score < 5 has ~96–99% sensitivity for ruling out appendicitis in adults). Consider discharge with safety-netting or observation and reassessment; imaging if clinical concern persists."}, {"min": 5, "max": 6, "label": "Possible appendicitis", "text": "Intermediate probability. Observe and re-score, or image (ultrasound first in children/young women; CT in adults)."}, {"min": 7, "max": 8, "label": "Probable appendicitis", "text": "High probability. Surgical referral; imaging per local pathway (many centres still confirm with CT/US before surgery)."}, {"min": 9, "max": 10, "label": "Very probable appendicitis", "text": "Very high probability. Surgical referral for appendicectomy."}], "src": "Alvarado A. Ann Emerg Med 1986; Ohle R et al. BMC Med 2011 (systematic review: score < 5 rules out, sensitivity 99% in adults; over-predicts in women and children)", "note": "Good for ruling OUT (score < 5) but poor for ruling IN, especially in women of reproductive age and children, where it over-predicts; it does not replace imaging. The AIR score and Adult Appendicitis Score perform better (WSES Jerusalem guidelines 2020). Add urine hCG in women."}, {"id": "air", "name": "AIR score (Appendicitis Inflammatory Response)", "kind": "score", "group": "Abdominal", "use": "Grade the probability of appendicitis in suspected cases using clinical signs and inflammatory markers; preferred over Alvarado by WSES 2020.", "items": [{"k": "vom", "label": "Vomiting", "opts": [["No", 0], ["Yes", 1]]}, {"k": "rif", "label": "Pain in the right inferior fossa", "opts": [["No", 0], ["Yes", 1]]}, {"k": "reb", "label": "Rebound tenderness or muscular defence", "opts": [["None", 0], ["Light", 1], ["Medium", 2], ["Strong", 3]]}, {"k": "temp", "label": "Body temperature ≥ 38.5 °C", "opts": [["No", 0], ["Yes", 1]]}, {"k": "pmn", "label": "Polymorphonuclear leucocytes (neutrophil proportion)", "opts": [["< 70%", 0], ["70–84%", 1], ["≥ 85%", 2]]}, {"k": "wbc", "label": "White cell count (× 10⁹/L)", "opts": [["< 10.0", 0], ["10.0–14.9", 1], ["≥ 15.0", 2]]}, {"k": "crp", "label": "CRP (mg/L)", "opts": [["< 10", 0], ["10–49", 1], ["≥ 50", 2]]}], "bands": [{"min": 0, "max": 4, "label": "Low probability", "text": "Appendicitis unlikely: outpatient follow-up or observation with repeat scoring if symptoms persist; imaging not routinely needed (score ≥ 5 has sensitivity 92%, so < 5 misses ~8% — safety-net)."}, {"min": 5, "max": 8, "label": "Indeterminate probability", "text": "Admit for in-hospital observation and re-scoring, or imaging (ultrasound/CT) and/or diagnostic laparoscopy per local pathway."}, {"min": 9, "max": 12, "label": "High probability", "text": "Appendicitis very likely (score ≥ 8: specificity 97%). Surgical referral — consider proceeding to surgery without further imaging."}], "src": "Andersson M, Andersson RE. World J Surg 2008; validation: de Castro SM et al. World J Surg 2012; WSES Jerusalem guidelines 2020 (Di Saverio S et al. World J Emerg Surg 2020)", "note": "Outperforms Alvarado for discrimination, particularly in advanced appendicitis, and is less affected by sex and age. Reassess over 4–8 h — the inflammatory response evolves. Still does not replace imaging in intermediate cases; in children consider the pARC or Pediatric Appendicitis Score."}, {"id": "centor", "name": "Centor / McIsaac score", "kind": "score", "group": "Infection", "use": "Estimate the likelihood of group A streptococcal pharyngitis in acute sore throat to guide antibiotic prescribing or testing.", "items": [{"k": "exud", "label": "Tonsillar exudate (or swelling)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "nodes", "label": "Tender anterior cervical lymphadenopathy", "opts": [["No", 0], ["Yes", 1]]}, {"k": "cough", "label": "Absence of cough", "opts": [["Cough present", 0], ["No cough", 1]]}, {"k": "fever", "label": "History of fever (> 38 °C)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "age", "label": "Age (McIsaac modification; choose 15–44 for the original Centor)", "opts": [["3–14 years", 1], ["15–44 years", 0], ["≥ 45 years", -1]]}], "bands": [{"min": -1, "max": 0, "label": "Very low", "text": "GAS probability ~1–2.5%. No antibiotics, no testing. Self-care, analgesia, safety-netting."}, {"min": 1, "max": 1, "label": "Low", "text": "GAS probability ~5–10%. No antibiotics (NICE NG84: Centor 0–2 → no antibiotic)."}, {"min": 2, "max": 2, "label": "Low–intermediate", "text": "GAS probability ~11–17%. NICE NG84: no antibiotic or, where available, rapid antigen/throat culture to guide treatment."}, {"min": 3, "max": 3, "label": "Intermediate", "text": "GAS probability ~28–35%. NICE NG84: consider immediate or back-up (delayed) antibiotic — phenoxymethylpenicillin 5–10 days first line."}, {"min": 4, "max": 5, "label": "High", "text": "GAS probability ~51–53%. NICE NG84: consider immediate antibiotic (or back-up prescription); phenoxymethylpenicillin first line, clarithromycin if penicillin-allergic."}], "src": "Centor RM et al. Med Decis Making 1981; McIsaac WJ et al. CMAJ 1998 and JAMA 2004 (age modification); NICE NG84 Sore throat (acute): antimicrobial prescribing 2018", "note": "NICE NG84 accepts either Centor (3–4 → consider antibiotics) or FeverPAIN (4–5 → consider antibiotics). Does not detect glandular fever, peritonsillar abscess or epiglottitis — look for red flags (stridor, trismus, drooling, unilateral swelling, systemic toxicity). Point-of-care Strep A testing is not routine in UK primary care."}, {"id": "feverpain", "name": "FeverPAIN score", "kind": "score", "group": "Infection", "use": "UK-derived score for streptococcal sore throat to target antibiotic prescribing (NICE NG84).", "items": [{"k": "fever", "label": "Fever in the previous 24 hours", "opts": [["No", 0], ["Yes", 1]]}, {"k": "pur", "label": "Purulence (pus on tonsils)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "attend", "label": "Attend rapidly (within 3 days of symptom onset)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "infl", "label": "Severely inflamed tonsils", "opts": [["No", 0], ["Yes", 1]]}, {"k": "cough", "label": "No cough or coryza", "opts": [["Cough/coryza present", 0], ["No cough or coryza", 1]]}], "bands": [{"min": 0, "max": 1, "label": "Low", "text": "13–18% likelihood of streptococcus. No antibiotic; self-care and safety-netting (NICE NG84)."}, {"min": 2, "max": 3, "label": "Intermediate", "text": "34–40% likelihood of streptococcus. NICE NG84: no antibiotic or a back-up (delayed) antibiotic prescription to use if no improvement in 3–5 days or worsening."}, {"min": 4, "max": 5, "label": "High", "text": "62–65% likelihood of streptococcus. NICE NG84: consider immediate antibiotic (phenoxymethylpenicillin 5–10 days; clarithromycin if penicillin-allergic) or a back-up prescription."}], "src": "Little P et al. BMJ 2013 (PRISM study); NICE NG84 Sore throat (acute) 2018", "note": "Derived in UK primary care in patients ≥ 3 years. Validated to reduce antibiotic use by ~30% without worse outcomes. Exclude red flags (stridor, trismus, drooling, peritonsillar swelling, severe systemic illness). FeverPAIN or Centor may be used — NICE recommends either."}, {"id": "gbs", "name": "Glasgow–Blatchford score", "kind": "score", "group": "Abdominal", "use": "Pre-endoscopy risk stratification of acute upper GI bleeding: predicts need for intervention (transfusion, endoscopic therapy, surgery) and identifies patients safe for outpatient management.", "items": [{"k": "urea", "label": "Blood urea (mmol/L)", "opts": [["< 6.5", 0], ["6.5–7.9", 2], ["8.0–9.9", 3], ["10.0–24.9", 4], ["≥ 25", 6]]}, {"k": "hbm", "label": "Haemoglobin — MEN (g/L) (women: select 'not applicable' and use the next item)", "opts": [["Not applicable (female)", 0], ["≥ 130", 0], ["120–129", 1], ["100–119", 3], ["< 100", 6]]}, {"k": "hbf", "label": "Haemoglobin — WOMEN (g/L) (men: select 'not applicable')", "opts": [["Not applicable (male)", 0], ["≥ 120", 0], ["100–119", 1], ["< 100", 6]]}, {"k": "sbp", "label": "Systolic blood pressure (mmHg)", "opts": [["≥ 110", 0], ["100–109", 1], ["90–99", 2], ["< 90", 3]]}, {"k": "hr", "label": "Pulse ≥ 100 /min", "opts": [["No", 0], ["Yes", 1]]}, {"k": "mel", "label": "Presentation with melaena", "opts": [["No", 0], ["Yes", 1]]}, {"k": "sync", "label": "Presentation with syncope", "opts": [["No", 0], ["Yes", 2]]}, {"k": "liver", "label": "Hepatic disease (known history, or clinical/laboratory evidence of chronic or acute liver disease)", "opts": [["No", 0], ["Yes", 2]]}, {"k": "hf", "label": "Cardiac failure (known history, or clinical/echo evidence)", "opts": [["No", 0], ["Yes", 2]]}], "bands": [{"min": 0, "max": 0, "label": "Very low risk — consider outpatient management", "text": "Score 0: < 1% need intervention. NICE CG141: consider early discharge with outpatient endoscopy. BSG 2021 extends this to GBS ≤ 1."}, {"min": 1, "max": 1, "label": "Low risk", "text": "BSG 2021: GBS ≤ 1 identifies patients who can be managed as outpatients (NPV ~99%) with urgent outpatient endoscopy. NICE CG141 uses a stricter cut-off of 0."}, {"min": 2, "max": 5, "label": "Moderate risk — admit", "text": "Admit; endoscopy within 24 h of admission (immediately after resuscitation if unstable). Monitor; transfuse to Hb > 70 g/L (> 80 g/L if cardiovascular disease)."}, {"min": 6, "max": 29, "label": "High risk — admit, early endoscopy", "text": "Score ≥ 6: > 50% risk of needing intervention. Resuscitate, early (within 24 h, sooner if unstable) endoscopy, senior review, consider critical care. Consider IV PPI/terlipressin and antibiotics if varices suspected."}], "src": "Blatchford O, Murray WR, Blatchford M. Lancet 2000; Stanley AJ et al. Lancet 2009 and BMJ 2017 (validation); NICE CG141 2012 (updated 2016); BSG UK guideline on acute upper GI bleeding, Gut 2021", "note": "Score before endoscopy; the full (post-endoscopy) Rockall score is used after. GBS outperforms pre-endoscopy Rockall and AIMS65 for predicting need for intervention. Haemoglobin bands are sex-specific — select the 'not applicable' option on the item that does not apply. Values are shown in g/L (original paper used g/dL: men 12.0–12.9/10.0–11.9/< 10; women 10.0–11.9/< 10)."}, {"id": "abcd2", "name": "ABCD² score", "kind": "score", "group": "Neuro", "use": "Historic estimate of early stroke risk after a transient ischaemic attack; now largely superseded for triage because all suspected TIAs need urgent specialist assessment.", "items": [{"k": "age", "label": "Age ≥ 60 years", "opts": [["No", 0], ["Yes", 1]]}, {"k": "bp", "label": "Blood pressure ≥ 140/90 mmHg at first assessment", "opts": [["No", 0], ["Yes", 1]]}, {"k": "clin", "label": "Clinical features", "opts": [["Other symptoms", 0], ["Speech disturbance without weakness", 1], ["Unilateral weakness", 2]]}, {"k": "dur", "label": "Duration of symptoms", "opts": [["< 10 minutes", 0], ["10–59 minutes", 1], ["≥ 60 minutes", 2]]}, {"k": "dm", "label": "Diabetes mellitus", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 3, "label": "Low", "text": "2-day stroke risk ~1.0%; 7-day ~1.2%; 90-day ~3.1%. Still requires specialist assessment within 24 h (NICE NG128)."}, {"min": 4, "max": 5, "label": "Moderate", "text": "2-day stroke risk ~4.1%; 7-day ~5.9%; 90-day ~9.8%. Specialist assessment within 24 h."}, {"min": 6, "max": 7, "label": "High", "text": "2-day stroke risk ~8.1%; 7-day ~11.7%; 90-day ~17.8%. Specialist assessment within 24 h."}], "src": "Johnston SC et al. Lancet 2007; Wardlaw JM et al. Neurology 2015 (systematic review — poor discrimination); NICE NG128 Stroke and TIA 2019 (updated 2022)", "note": "NICE NG128 (2019) states: 'Do not use scoring systems such as ABCD2 to assess risk of subsequent stroke or to inform urgency of referral' — all suspected TIA → aspirin 300 mg immediately and specialist assessment within 24 h. Also removed from AHA/ASA and Australian guidance for triage. Retained here for teaching only. Misses posterior-circulation and non-motor TIAs and ignores carotid stenosis/AF, which drive risk."}, {"id": "cha2ds2va", "name": "CHA₂DS₂-VA score", "kind": "score", "group": "Cardiac", "use": "Estimate thromboembolic risk in atrial fibrillation or flutter to decide on oral anticoagulation (ESC 2024 — sex criterion removed).", "items": [{"k": "c", "label": "Congestive heart failure (symptomatic HF or objective LV dysfunction, incl. HFpEF)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "h", "label": "Hypertension (or on antihypertensive treatment)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "a2", "label": "Age ≥ 75 years", "opts": [["No", 0], ["Yes", 2]]}, {"k": "d", "label": "Diabetes mellitus (type 1 or 2, or on glucose-lowering therapy)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "s2", "label": "Prior stroke, TIA or arterial thromboembolism", "opts": [["No", 0], ["Yes", 2]]}, {"k": "v", "label": "Vascular disease (prior MI, coronary artery disease, peripheral artery disease, aortic plaque)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "a", "label": "Age 65–74 years", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "Low risk", "text": "Oral anticoagulation not recommended (annual stroke risk < 1%). Reassess at every review and at least annually — risk factors accumulate."}, {"min": 1, "max": 1, "label": "Intermediate — OAC should be considered", "text": "ESC 2024 Class IIa: oral anticoagulation should be considered, with shared decision-making and attention to bleeding risk and patient preference."}, {"min": 2, "max": 9, "label": "OAC recommended", "text": "ESC 2024 Class I: oral anticoagulation (DOAC preferred over VKA except in mechanical valves or moderate–severe mitral stenosis) regardless of AF pattern. Do not withhold for bleeding risk alone — address modifiable bleeding factors."}], "src": "Van Gelder IC et al. 2024 ESC Guidelines for the management of atrial fibrillation. Eur Heart J 2024", "note": "Replaces CHA₂DS₂-VASc: female sex was removed because it is an age-dependent modifier rather than an independent risk factor; thresholds are therefore the same for men and women (score ≥ 2 = OAC; 1 = consider). NICE NG196 (2021) still cites CHA₂DS₂-VASc. Note that both 'age' items cannot be scored together (select ≥ 75 OR 65–74). Use ORBIT (NICE) or HAS-BLED to address bleeding risk, not to withhold OAC."}, {"id": "hasbled", "name": "HAS-BLED score", "kind": "score", "group": "Cardiac", "use": "Estimate 1-year major bleeding risk on anticoagulation for AF and identify modifiable bleeding risk factors; not a reason to withhold anticoagulation.", "items": [{"k": "h", "label": "Hypertension — uncontrolled, systolic > 160 mmHg", "opts": [["No", 0], ["Yes", 1]]}, {"k": "ar", "label": "Abnormal renal function (dialysis, transplant, creatinine > 200 µmol/L)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "al", "label": "Abnormal liver function (cirrhosis, or bilirubin > 2× ULN with AST/ALT/ALP > 3× ULN)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "s", "label": "Stroke history (ischaemic or haemorrhagic)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "b", "label": "Bleeding history or predisposition (major bleed, anaemia, severe thrombocytopenia)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "l", "label": "Labile INR (time in therapeutic range < 60% on warfarin)", "opts": [["No / not on warfarin", 0], ["Yes", 1]]}, {"k": "e", "label": "Elderly — age > 65 years", "opts": [["No", 0], ["Yes", 1]]}, {"k": "d1", "label": "Drugs — concomitant antiplatelet or NSAID", "opts": [["No", 0], ["Yes", 1]]}, {"k": "d2", "label": "Alcohol — ≥ 8 drinks/week", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "Low", "text": "Major bleeding ~1.1 per 100 patient-years. Anticoagulate as indicated; routine review."}, {"min": 1, "max": 1, "label": "Low", "text": "Major bleeding ~1.0 per 100 patient-years. Anticoagulate as indicated."}, {"min": 2, "max": 2, "label": "Moderate", "text": "Major bleeding ~1.9 per 100 patient-years. Address modifiable factors (BP, NSAIDs, alcohol, INR control)."}, {"min": 3, "max": 9, "label": "High", "text": "Major bleeding ~3.7–12.5 per 100 patient-years (3: 3.7%, 4: 8.7%, 5: 12.5%). Correct modifiable risk factors, review more frequently (e.g. 4-weekly) — do NOT withhold anticoagulation on this basis alone."}], "src": "Pisters R et al. Chest 2010; Lip GYH et al. JACC 2011 (validation); ESC 2024 AF guideline", "note": "ESC 2024 recommends using bleeding scores to identify and modify risk factors rather than to withhold OAC. NICE NG196 (2021) recommends ORBIT instead of HAS-BLED. Many bleeding factors (age, stroke, hypertension) are also stroke risk factors, so high HAS-BLED usually means high CHA₂DS₂-VA too."}, {"id": "ottawa-sah", "name": "Ottawa subarachnoid haemorrhage rule", "kind": "score", "group": "Neuro", "use": "In alert adults (≥ 15 years) with a new severe non-traumatic headache peaking within 1 hour, identify who can have SAH ruled out WITHOUT investigation; any criterion present → investigate.", "items": [{"k": "age", "label": "Age ≥ 40 years", "opts": [["No", 0], ["Yes", 1]]}, {"k": "neck", "label": "Neck pain or stiffness (symptom)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "loc", "label": "Witnessed loss of consciousness", "opts": [["No", 0], ["Yes", 1]]}, {"k": "exert", "label": "Onset during exertion", "opts": [["No", 0], ["Yes", 1]]}, {"k": "thunder", "label": "Thunderclap headache (instantly peaking pain)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "flex", "label": "Limited neck flexion on examination (unable to touch chin to chest, or within 2 fingerbreadths)", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "Rule negative — SAH effectively excluded", "text": "No criteria present: SAH very unlikely (sensitivity 100% in derivation and validation, 95% CI lower bound ~97%). Investigation for SAH not required by the rule; consider other serious causes of headache."}, {"min": 1, "max": 6, "label": "Rule positive — cannot exclude SAH", "text": "One or more criteria present: investigate — non-contrast CT head (≈100% sensitive if done within 6 h of onset on a modern scanner and read by a neuroradiologist); if CT negative beyond 6 h, lumbar puncture ≥ 12 h after onset for xanthochromia, or CT angiography per local pathway. Specificity is only ~15%, so most positives are not SAH."}], "src": "Perry JJ et al. JAMA 2013 (derivation); Perry JJ et al. CMAJ 2017 (validation, 1153 patients, sensitivity 100%)", "note": "Inclusion: alert (GCS 15), age ≥ 15, new severe atraumatic headache reaching maximal intensity within 1 h, presenting within 14 days. EXCLUDE: new neurological deficit, previous aneurysm, SAH or brain tumour, history of recurrent similar headaches (≥ 3 episodes over > 6 months), head trauma within 7 days, papilloedema. A rule-OUT tool only — it does not diagnose SAH."}, {"id": "pecarn-u2", "name": "PECARN head injury rule — under 2 years", "kind": "score", "group": "Trauma", "use": "Identify children < 2 years with minor blunt head trauma (GCS 14–15) at very low risk of clinically important traumatic brain injury (ciTBI) who do not need CT.", "items": [{"k": "gcs", "label": "HIGH RISK: GCS ≤ 14, or other signs of altered mental status (agitation, somnolence, repetitive questioning, slow response)", "opts": [["No", 0], ["Yes", 10]]}, {"k": "skull", "label": "HIGH RISK: Palpable skull fracture", "opts": [["No", 0], ["Yes", 10]]}, {"k": "haem", "label": "INTERMEDIATE: Occipital, parietal or temporal scalp haematoma (frontal does not count)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "loc", "label": "INTERMEDIATE: Loss of consciousness ≥ 5 seconds", "opts": [["No", 0], ["Yes", 1]]}, {"k": "mech", "label": "INTERMEDIATE: Severe mechanism (MVC with ejection, death of another passenger or rollover; pedestrian or unhelmeted cyclist struck by motor vehicle; fall > 0.9 m (3 feet); head struck by high-impact object)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "beh", "label": "INTERMEDIATE: Not acting normally according to parent", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "Very low risk — CT not recommended", "text": "No predictors: ciTBI risk < 0.02%. CT not indicated; discharge with head-injury advice."}, {"min": 1, "max": 9, "label": "Intermediate risk — observation vs CT", "text": "ciTBI risk ~0.9%. Observation (4–6 h) or CT based on clinical judgement: physician experience, multiple vs isolated findings, worsening symptoms, age < 3 months, parental preference. Isolated single finding → observation usually sufficient."}, {"min": 10, "max": 24, "label": "High risk — CT recommended", "text": "ciTBI risk ~4.4%. CT head recommended."}], "src": "Kuppermann N et al. PECARN. Lancet 2009; validation: Easter JS et al. Ann Emerg Med 2014; Babl FE et al. Lancet 2017 (APHIRST)", "note": "Applies to blunt head trauma within 24 h with GCS 14–15. Excludes: trivial mechanism (ground-level fall, walking/running into stationary object with no signs except scalp abrasion/laceration), penetrating trauma, known brain tumour, pre-existing neurological disorder, bleeding disorder, ventricular shunt, previous imaging for this injury. UK practice: NICE NG232 2023 criteria for children differ (e.g. CT within 1 h for ≥ 2 risk factors). Sensitivity 100% in the under-2 derivation cohort; ciTBI = death, neurosurgery, intubation > 24 h, or admission ≥ 2 nights for TBI."}, {"id": "pecarn-2plus", "name": "PECARN head injury rule — 2 to 17 years", "kind": "score", "group": "Trauma", "use": "Identify children ≥ 2 years with minor blunt head trauma (GCS 14–15) at very low risk of clinically important traumatic brain injury (ciTBI) who do not need CT.", "items": [{"k": "gcs", "label": "HIGH RISK: GCS ≤ 14, or other signs of altered mental status (agitation, somnolence, repetitive questioning, slow response)", "opts": [["No", 0], ["Yes", 10]]}, {"k": "basal", "label": "HIGH RISK: Signs of basilar skull fracture (haemotympanum, CSF leak, Battle's sign, 'racoon' eyes)", "opts": [["No", 0], ["Yes", 10]]}, {"k": "loc", "label": "INTERMEDIATE: History of any loss of consciousness", "opts": [["No", 0], ["Yes", 1]]}, {"k": "vom", "label": "INTERMEDIATE: History of vomiting", "opts": [["No", 0], ["Yes", 1]]}, {"k": "mech", "label": "INTERMEDIATE: Severe mechanism (MVC with ejection, death of another passenger or rollover; pedestrian or unhelmeted cyclist struck by motor vehicle; fall > 1.5 m (5 feet); head struck by high-impact object)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "ha", "label": "INTERMEDIATE: Severe headache", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "Very low risk — CT not recommended", "text": "No predictors: ciTBI risk < 0.05%. CT not indicated; discharge with head-injury advice."}, {"min": 1, "max": 9, "label": "Intermediate risk — observation vs CT", "text": "ciTBI risk ~0.9%. Observation (4–6 h) or CT based on clinical judgement: physician experience, multiple vs isolated findings, worsening symptoms or signs after observation, parental preference. Isolated vomiting or isolated LOC → observation usually sufficient."}, {"min": 10, "max": 24, "label": "High risk — CT recommended", "text": "ciTBI risk ~4.3%. CT head recommended."}], "src": "Kuppermann N et al. PECARN. Lancet 2009; validation: Easter JS et al. Ann Emerg Med 2014; Babl FE et al. Lancet 2017 (APHIRST)", "note": "Applies to blunt head trauma within 24 h with GCS 14–15, age 2–17 years. Same exclusions as the under-2 rule (trivial mechanism, penetrating injury, bleeding disorder, shunt, known tumour, prior imaging). Sensitivity 96.8% (derivation), 100% in the validation cohort for the ≥ 2 group. UK practice: NICE NG232 2023 criteria for children differ. PECARN, CATCH and CHALICE were compared head-to-head in APHIRST: PECARN had the highest sensitivity."}, {"id": "kocher", "name": "Kocher criteria (septic arthritis of the hip in children)", "kind": "score", "group": "MSK", "use": "Differentiate septic arthritis from transient synovitis in a child with an acutely irritable hip.", "items": [{"k": "nwb", "label": "Non-weight-bearing on the affected side", "opts": [["No", 0], ["Yes", 1]]}, {"k": "esr", "label": "ESR ≥ 40 mm/h", "opts": [["No", 0], ["Yes", 1]]}, {"k": "fever", "label": "Fever > 38.5 °C (history or measured)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "wbc", "label": "White cell count > 12 × 10⁹/L", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 0, "label": "Very low probability", "text": "< 0.2% (derivation) / 2% (validation) probability of septic arthritis. Likely transient synovitis — observe, analgesia, review within 24–48 h; ultrasound if effusion suspected."}, {"min": 1, "max": 1, "label": "Low probability", "text": "~3% (derivation) / 9.5% (validation). Consider ultrasound; close review. Add CRP (> 20 mg/L) as a fifth predictor (Caird 2006)."}, {"min": 2, "max": 2, "label": "Intermediate probability", "text": "~40% (derivation) / 35% (validation). Urgent ultrasound ± aspiration; orthopaedic referral."}, {"min": 3, "max": 3, "label": "High probability", "text": "~93% (derivation) / 73% (validation). Urgent orthopaedic referral for aspiration ± washout; blood cultures; IV antibiotics after aspiration."}, {"min": 4, "max": 4, "label": "Very high probability", "text": "~99% (derivation) / 93% (validation). Treat as septic arthritis — emergency aspiration/washout, blood cultures, IV antibiotics."}], "src": "Kocher MS et al. J Bone Joint Surg Am 1999 (derivation); Kocher MS et al. JBJS 2004 (validation — lower predicted probabilities); Caird MS et al. JBJS 2006 (adds CRP > 20 mg/L)", "note": "Validation studies show lower probabilities than the derivation values, so treat the percentages as approximate. Caird's modification adds CRP > 20 mg/L (5 predictors: 5/5 = 98%). Does not apply to other joints, neonates, immunocompromised children, or those already on antibiotics. Never withhold aspiration on the basis of a low score if clinical suspicion is high."}, {"id": "twist", "name": "TWIST score (Testicular Workup for Ischemia and Suspected Torsion)", "kind": "score", "group": "General", "use": "Stratify the risk of testicular torsion in acute scrotal pain to decide between clinical reassurance, ultrasound, and direct surgical exploration.", "items": [{"k": "swell", "label": "Testicular swelling", "opts": [["No", 0], ["Yes", 2]]}, {"k": "hard", "label": "Hard testis on palpation", "opts": [["No", 0], ["Yes", 2]]}, {"k": "crem", "label": "Absent cremasteric reflex", "opts": [["Present", 0], ["Absent", 1]]}, {"k": "nv", "label": "Nausea or vomiting", "opts": [["No", 0], ["Yes", 1]]}, {"k": "high", "label": "High-riding testis", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 2, "label": "Low risk", "text": "Torsion unlikely (pooled sensitivity of 'score > 2' 98.4%; NPV ~100% in derivation). Ultrasound may be omitted in the hands of an experienced examiner, but in UK practice most still obtain Doppler ultrasound or urology review — never delay if clinical doubt."}, {"min": 3, "max": 4, "label": "Intermediate risk", "text": "Urgent Doppler ultrasound (do not let imaging delay surgery if it will take > 1 h); urology review."}, {"min": 5, "max": 7, "label": "High risk", "text": "PPV ~100% in derivation (specificity 97.5% pooled). Immediate urology referral for scrotal exploration without waiting for ultrasound — testicular salvage falls sharply after 6 h."}], "src": "Barbosa JA et al. J Urol 2013 (derivation); Sheth KR et al. J Urol 2016 (validation in children); Qin KR, Qu LG. Systematic review and meta-analysis, J Urol 2022", "note": "Derived in a paediatric/adolescent population (mean age ~11); validated in adults with similar performance (Frohlich 2017). Scoring performed by non-urologists was less accurate in some studies. Treat torsion as a surgical emergency; the score should never delay exploration in a high-suspicion case."}, {"id": "lrinec", "name": "LRINEC score (Laboratory Risk Indicator for Necrotising Fasciitis)", "kind": "score", "group": "Infection", "use": "Use laboratory values to distinguish necrotising soft-tissue infection from severe cellulitis/abscess — a RULE-IN aid only; it cannot exclude necrotising fasciitis.", "items": [{"k": "crp", "label": "CRP ≥ 150 mg/L", "opts": [["< 150", 0], ["≥ 150", 4]]}, {"k": "wbc", "label": "White cell count (× 10⁹/L)", "opts": [["< 15", 0], ["15–25", 1], ["> 25", 2]]}, {"k": "hb", "label": "Haemoglobin (g/L)", "opts": [["> 135", 0], ["110–135", 1], ["< 110", 2]]}, {"k": "na", "label": "Sodium < 135 mmol/L", "opts": [["≥ 135", 0], ["< 135", 2]]}, {"k": "cr", "label": "Creatinine > 141 µmol/L", "opts": [["≤ 141", 0], ["> 141", 2]]}, {"k": "glu", "label": "Glucose > 10 mmol/L", "opts": [["≤ 10", 0], ["> 10", 1]]}], "bands": [{"min": 0, "max": 5, "label": "Low risk", "text": "< 50% probability in the derivation cohort — but sensitivity is poor (pooled ~68% for score ≥ 6), so a low score DOES NOT exclude necrotising fasciitis. If clinical suspicion exists (pain out of proportion, rapid progression, crepitus, bullae, systemic toxicity), obtain urgent surgical review/exploration regardless."}, {"min": 6, "max": 7, "label": "Intermediate risk", "text": "50–75% probability. Urgent surgical review; consider imaging (CT/MRI) only if it will not delay exploration; broad-spectrum antibiotics."}, {"min": 8, "max": 13, "label": "High risk", "text": "> 75% probability (PPV 92% in derivation). Immediate surgical exploration and debridement, broad-spectrum antibiotics including clindamycin, critical care."}], "src": "Wong CH et al. Crit Care Med 2004; Fernando SM et al. Ann Surg 2019 (meta-analysis: LRINEC ≥ 6 sensitivity 68.2%, specificity 84.8%)", "note": "Retrospectively derived; meta-analysis shows sensitivity of only ~68% — up to one-third of necrotising fasciitis cases score < 6. Necrotising fasciitis is a clinical and surgical diagnosis: the 'finger test'/exploration is the gold standard. Do not use the score to defer surgical review."}, {"id": "scorten", "name": "SCORTEN", "kind": "score", "group": "General", "use": "Predict mortality in Stevens–Johnson syndrome / toxic epidermal necrolysis using seven variables measured within the first 24 h of admission.", "items": [{"k": "age", "label": "Age ≥ 40 years", "opts": [["No", 0], ["Yes", 1]]}, {"k": "ca", "label": "Associated malignancy", "opts": [["No", 0], ["Yes", 1]]}, {"k": "hr", "label": "Heart rate ≥ 120 /min", "opts": [["No", 0], ["Yes", 1]]}, {"k": "bsa", "label": "Initial epidermal detachment > 10% body surface area (day 1)", "opts": [["No", 0], ["Yes", 1]]}, {"k": "urea", "label": "Serum urea > 10 mmol/L", "opts": [["No", 0], ["Yes", 1]]}, {"k": "bic", "label": "Serum bicarbonate < 20 mmol/L", "opts": [["No", 0], ["Yes", 1]]}, {"k": "glu", "label": "Serum glucose > 14 mmol/L (> 252 mg/dL)", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 1, "label": "Mortality ~3%", "text": "Predicted mortality 3.2%. Supportive care; dermatology review; consider transfer to a burns/specialist unit per BAD guidelines."}, {"min": 2, "max": 2, "label": "Mortality ~12%", "text": "Predicted mortality 12.1%. Specialist unit; stop culprit drug; supportive care with fluid, temperature and wound management."}, {"min": 3, "max": 3, "label": "Mortality ~35%", "text": "Predicted mortality 35.3%. Specialist burns/ICU care."}, {"min": 4, "max": 4, "label": "Mortality ~58%", "text": "Predicted mortality 58.3%. Specialist burns/ICU care."}, {"min": 5, "max": 7, "label": "Mortality ≥ 90%", "text": "Predicted mortality > 90%. Specialist burns/ICU care; early discussion of ceilings of care."}], "src": "Bastuji-Garin S et al. J Invest Dermatol 2000; BAD guidelines for SJS/TEN in adults, Br J Dermatol 2016", "note": "Calculate within 24 h of admission and repeat on day 3 for improved accuracy (Guégan 2006). Tends to over-predict mortality in some modern cohorts and under-predict in others (e.g. with respiratory involvement). Not validated in children. The glucose threshold in the original paper was > 14 mmol/L (some tables list 13.9 mmol/L = 250 mg/dL)."}, {"id": "glasgow-7", "name": "Glasgow 7-point checklist (pigmented lesions)", "kind": "score", "group": "General", "use": "Weighted checklist for a changing pigmented skin lesion to decide on urgent (2-week-wait) referral for suspected melanoma (NICE NG12).", "items": [{"k": "size", "label": "MAJOR: Change in size", "opts": [["No", 0], ["Yes", 2]]}, {"k": "shape", "label": "MAJOR: Irregular shape (or change in shape)", "opts": [["No", 0], ["Yes", 2]]}, {"k": "colour", "label": "MAJOR: Irregular colour (or change in colour)", "opts": [["No", 0], ["Yes", 2]]}, {"k": "diam", "label": "MINOR: Largest diameter ≥ 7 mm", "opts": [["No", 0], ["Yes", 1]]}, {"k": "infl", "label": "MINOR: Inflammation", "opts": [["No", 0], ["Yes", 1]]}, {"k": "ooze", "label": "MINOR: Oozing or crusting", "opts": [["No", 0], ["Yes", 1]]}, {"k": "sens", "label": "MINOR: Change in sensation (itch, altered sensation)", "opts": [["No", 0], ["Yes", 1]]}], "bands": [{"min": 0, "max": 2, "label": "Below referral threshold", "text": "Score < 3: melanoma less likely, but refer urgently anyway if any single major feature is present or there is strong clinical concern (NICE NG12). Consider dermoscopy; safety-net and review for change."}, {"min": 3, "max": 10, "label": "Refer — suspected cancer pathway (2 weeks)", "text": "Score ≥ 3: refer via the suspected-cancer (2-week-wait) pathway for melanoma (NICE NG12). Do not excise in primary care. Photograph and document."}], "src": "MacKie RM. Clinical recognition of early invasive malignant melanoma. BMJ 1990 (Glasgow checklist); Whited JD, Grichnik JM. JAMA 1998 (7-point sensitivity 79–100%, specificity 30–37%); NICE NG12 Suspected cancer 2015 (updated 2023)", "note": "High sensitivity but low specificity — it exists to avoid missing melanoma, not to diagnose it. NICE also permits referral on the basis of dermoscopy or any suspicious lesion. The ABCDE rule (Asymmetry, Border, Colour, Diameter > 6 mm, Evolving) is the alternative; nodular and amelanotic melanomas may score low on both. The 'ugly duckling' sign (a naevus unlike the patient's others) should prompt referral regardless of score."}, {"id": "parkland", "name": "Parkland (Baxter) burn resuscitation formula", "kind": "formula", "group": "Trauma", "use": "Estimate crystalloid volume for the first 24 h after a major burn (adults ≥ 20% TBSA, children ≥ 10%), half given in the first 8 h from the time of injury.", "inputs": [{"k": "wt", "label": "Weight", "unit": "kg", "min": 3, "max": 250, "step": 0.5}, {"k": "tbsa", "label": "Burn area (partial + full thickness, exclude erythema)", "unit": "% TBSA", "min": 1, "max": 100, "step": 1}], "expr": "4 * wt * tbsa", "unit": "mL in 24 h (Parkland 4 mL/kg/%)", "bands": [{"min": 0, "max": 100000, "label": "Parkland total", "text": "Give HALF of this volume in the first 8 h from the TIME OF INJURY (not arrival) and the remaining half over the next 16 h, as balanced crystalloid (Hartmann's/Ringer's lactate). The ABA 2023 starting rate is half this total (2 mL/kg/%TBSA) — see note. Titrate to urine output 0.5 mL/kg/h in adults (1 mL/kg/h in children < 30 kg)."}], "src": "Baxter CR, Shires T. Ann NY Acad Sci 1968; ISBI Practice Guidelines for Burn Care, Burns 2016; Cartotto R et al. American Burn Association Clinical Practice Guidelines on Burn Shock Resuscitation, J Burn Care Res 2024 (published online Dec 2023)", "note": "2026 caveat: the ABA 2023 guideline and ISBI 2016 recommend STARTING at 2 mL/kg/%TBSA (adults ≥ 20% TBSA) rather than 4, because Parkland frequently causes 'fluid creep' (over-resuscitation, compartment syndromes, ARDS); titrate hourly to urine output rather than to the formula. Children: 3 mL/kg/%TBSA plus maintenance dextrose-containing fluid (Holliday–Segar). Electrical and inhalation injuries often need more. The formula is a starting estimate only; the volume already given pre-hospital counts toward the first 8-h half."}, {"id": "shock-index", "name": "Shock index", "kind": "formula", "group": "General", "use": "Heart rate divided by systolic BP — an early marker of haemodynamic compromise (haemorrhage, sepsis, PE) that precedes hypotension.", "inputs": [{"k": "hr", "label": "Heart rate", "unit": "/min", "min": 20, "max": 250, "step": 1}, {"k": "sbp", "label": "Systolic BP", "unit": "mmHg", "min": 40, "max": 250, "step": 1}], "expr": "hr / sbp", "unit": "", "bands": [{"min": 0, "max": 0.49, "label": "Low", "text": "Below the normal range — seen with bradycardia or hypertension; interpret in context (beta-blockade, athletes, raised ICP)."}, {"min": 0.5, "max": 0.7, "label": "Normal", "text": "Normal range 0.5–0.7 in healthy adults."}, {"min": 0.71, "max": 0.89, "label": "Borderline", "text": "Mildly raised: in trauma, SI > 0.7 predicts transfusion need better than HR or SBP alone; in PE, SI ≥ 0.8 is a high-risk marker. Reassess and look for occult bleeding/sepsis."}, {"min": 0.9, "max": 1.29, "label": "Raised", "text": "SI ≥ 0.9 is associated with increased mortality, massive transfusion and ICU admission in trauma and sepsis; ≥ 1.0 in PE (and in ESC PE guidance) indicates haemodynamic instability. Activate massive-haemorrhage/sepsis pathways as appropriate."}, {"min": 1.3, "max": 10, "label": "Very high", "text": "SI ≥ 1.3: very high risk of massive transfusion and death in trauma (Mutschler 2013 class IV). Immediate resuscitation."}], "src": "Allgöwer M, Burri C. 1967; Rady MY et al. Ann Emerg Med 1994; Mutschler M et al. Crit Care 2013 (TraumaRegister DGU classes: < 0.6, 0.6–1.0, 1.0–1.4, ≥ 1.4); ESC 2019 PE guideline", "note": "Unreliable with beta-blockers, pacemakers, pregnancy (use the modified shock index or obstetric values; SI ≥ 0.9 abnormal in obstetric haemorrhage), and in children (age-adjusted SIPA: > 1.22 for 4–6 y, > 1.0 for 7–12 y, > 0.9 for 13–16 y). Modified SI = HR/MAP (normal 0.7–1.3)."}, {"id": "map", "name": "Mean arterial pressure", "kind": "formula", "group": "Cardiac", "use": "Estimate mean arterial pressure from a non-invasive BP; the perfusion pressure target in sepsis and critical care.", "inputs": [{"k": "sbp", "label": "Systolic BP", "unit": "mmHg", "min": 40, "max": 260, "step": 1}, {"k": "dbp", "label": "Diastolic BP", "unit": "mmHg", "min": 20, "max": 160, "step": 1}], "expr": "dbp + (sbp - dbp) / 3", "unit": "mmHg", "bands": [{"min": 0, "max": 59, "label": "Critically low", "text": "MAP < 60: organ perfusion (brain, kidneys, coronaries) is compromised. Immediate resuscitation; vasopressors if fluid-unresponsive."}, {"min": 60, "max": 64, "label": "Low", "text": "Below the sepsis target of ≥ 65 mmHg (Surviving Sepsis Campaign 2021). Fluids ± noradrenaline; higher target (≥ 80) may be needed in chronic hypertension."}, {"min": 65, "max": 100, "label": "Normal / target", "text": "Normal MAP 70–100 mmHg; ≥ 65 is the resuscitation target in sepsis. In raised ICP, aim MAP to keep cerebral perfusion pressure (MAP − ICP) 60–70 mmHg."}, {"min": 101, "max": 200, "label": "Raised", "text": "MAP > 100: hypertension. Context determines action — in acute stroke, intracranial haemorrhage or hypertensive emergency, follow condition-specific BP targets rather than MAP alone."}], "src": "Standard physiological formula (DBP + ⅓ pulse pressure); Surviving Sepsis Campaign 2021 (MAP ≥ 65 target)", "note": "The one-third rule assumes a normal heart rate — at tachycardia the true MAP is closer to the arithmetic mean of SBP and DBP; invasive arterial lines integrate the waveform directly. Oscillometric cuffs measure MAP directly and derive SBP/DBP."}, {"id": "anion-gap", "name": "Anion gap", "kind": "formula", "group": "General", "use": "Classify metabolic acidosis (raised vs normal gap) and detect unmeasured anions (lactate, ketones, toxic alcohols, uraemia).", "inputs": [{"k": "na", "label": "Sodium", "unit": "mmol/L", "min": 100, "max": 180, "step": 1}, {"k": "cl", "label": "Chloride", "unit": "mmol/L", "min": 60, "max": 140, "step": 1}, {"k": "hco3", "label": "Bicarbonate", "unit": "mmol/L", "min": 2, "max": 50, "step": 1}], "expr": "na - (cl + hco3)", "unit": "mmol/L", "bands": [{"min": -10, "max": 3, "label": "Low", "text": "Low anion gap: hypoalbuminaemia (most common), paraproteinaemia (myeloma), bromide/lithium, laboratory error. Correct for albumin before interpreting."}, {"min": 4, "max": 12, "label": "Normal", "text": "Normal range ~4–12 mmol/L with modern ion-selective electrodes (older reference 8–16 when potassium is included). A metabolic acidosis with a normal gap is hyperchloraemic: GI bicarbonate loss, renal tubular acidosis, saline infusion, acetazolamide — check the urinary anion gap."}, {"min": 13, "max": 19, "label": "Mildly raised", "text": "Borderline — may be normal in some labs or reflect early lactic/keto-acidosis. Check lactate, ketones, renal function; correct for albumin (hypoalbuminaemia masks a raised gap)."}, {"min": 20, "max": 80, "label": "Raised", "text": "Raised anion gap metabolic acidosis: lactate, ketones (DKA, alcoholic, starvation), uraemia, toxins (methanol, ethylene glycol, salicylate, metformin, paracetamol/pyroglutamic acid) — 'GOLDMARK'. Gap > 20 almost always significant. Calculate the delta ratio and osmolar gap if the cause is unclear."}], "src": "Emmett M, Narins RG. Medicine 1977; Figge J et al. Crit Care Med 1998 (albumin correction); Kraut JA, Madias NE. Clin J Am Soc Nephrol 2007 (reference ranges on modern analysers)", "note": "Albumin correction (Figge): corrected AG = AG + 0.25 × (40 − albumin in g/L) — each 10 g/L fall in albumin lowers the gap by ~2.5 mmol/L and can hide a significant acidosis in sick patients. This tool omits potassium (UK/US convention); if your lab's range was derived including K⁺, add it and use 8–16 (12–20 with K) as normal. Reference ranges are analyser-dependent — use the local range."}, {"id": "corrected-na", "name": "Corrected sodium for hyperglycaemia", "kind": "formula", "group": "General", "use": "Estimate what the serum sodium would be once glucose is normalised, in DKA/HHS — distinguishes true from pseudo-hyponatraemia caused by osmotic water shift.", "inputs": [{"k": "na", "label": "Measured sodium", "unit": "mmol/L", "min": 100, "max": 180, "step": 1}, {"k": "glu", "label": "Glucose", "unit": "mmol/L", "min": 2, "max": 120, "step": 0.1}], "expr": "na + 2.4 * (glu - 5.6) / 5.6", "unit": "mmol/L", "bands": [{"min": 0, "max": 124, "label": "Severe hyponatraemia (corrected)", "text": "True severe hyponatraemia persists after correction — assess volume status and osmolality; risk of cerebral oedema with rapid shifts. Follow hyponatraemia guidance (limit correction to ≤ 10 mmol/L in 24 h)."}, {"min": 125, "max": 134, "label": "Hyponatraemia (corrected)", "text": "Mild–moderate true hyponatraemia. In DKA/HHS, falling corrected sodium during treatment suggests excess free water — monitor 1–2-hourly and adjust fluids (JBDS 2023)."}, {"min": 135, "max": 145, "label": "Normal (corrected)", "text": "Measured hyponatraemia was dilutional (hyperglycaemia-induced); sodium will normalise as glucose falls. Ensure the corrected sodium does not rise > 10 mmol/L in 24 h."}, {"min": 146, "max": 200, "label": "Hypernatraemia (corrected)", "text": "True hypernatraemia (significant free-water deficit), common in HHS. Calculate the water deficit; in HHS aim for a fall in sodium of ≤ 10 mmol/L in 24 h and glucose fall of 4–6 mmol/L/h (JBDS 2022)."}], "src": "Hillier TA, Abbott RD, Barrett EJ. Am J Med 1999 (2.4 mmol/L per 100 mg/dL = 5.6 mmol/L of glucose above normal); Katz MA. NEJM 1973 (original 1.6 factor); JBDS-IP HHS guideline 2022 / DKA guideline 2023", "note": "Uses the Hillier factor (2.4 per 5.6 mmol/L glucose ≈ 0.43 per mmol/L), which better fits experimental data at glucose > 22 mmol/L; the older Katz factor (1.6 per 5.6 mmol/L ≈ 0.29 per mmol/L) under-corrects at very high glucose. JBDS HHS guidance uses the simpler Katz-type calculation; either is acceptable if applied consistently."}, {"id": "corrected-ca", "name": "Corrected (albumin-adjusted) calcium", "kind": "formula", "group": "General", "use": "Adjust total serum calcium for albumin so that hypo- or hypercalcaemia is not masked or mimicked by abnormal albumin.", "inputs": [{"k": "ca", "label": "Total calcium", "unit": "mmol/L", "min": 1, "max": 4, "step": 0.01}, {"k": "alb", "label": "Albumin", "unit": "g/L", "min": 10, "max": 60, "step": 1}], "expr": "ca + 0.02 * (40 - alb)", "unit": "mmol/L", "bands": [{"min": 0, "max": 1.89, "label": "Severe hypocalcaemia", "text": "Corrected Ca < 1.9: risk of tetany, laryngospasm, seizures, QT prolongation. IV calcium gluconate 10% 10–20 mL over 10 min with ECG monitoring if symptomatic; check magnesium, PTH, vitamin D, phosphate."}, {"min": 1.9, "max": 2.19, "label": "Hypocalcaemia", "text": "Mild–moderate: oral calcium ± vitamin D if asymptomatic; look for hypoparathyroidism (post-thyroidectomy), vitamin D deficiency, CKD, hypomagnesaemia, pancreatitis."}, {"min": 2.2, "max": 2.6, "label": "Normal", "text": "Normal corrected calcium (reference 2.2–2.6 mmol/L; lab-dependent)."}, {"min": 2.61, "max": 2.99, "label": "Mild hypercalcaemia", "text": "Usually asymptomatic. Check PTH (primary hyperparathyroidism vs malignancy), repeat, hydrate; review thiazides, lithium, vitamin D/calcium supplements."}, {"min": 3.0, "max": 3.49, "label": "Moderate hypercalcaemia", "text": "Symptoms likely (bones, stones, groans, moans). Admit if symptomatic: IV 0.9% saline 3–4 L/24 h, then IV bisphosphonate (zoledronate 4 mg) if malignancy; check PTH, PTHrP, myeloma screen."}, {"min": 3.5, "max": 6, "label": "Severe hypercalcaemia", "text": "Corrected Ca ≥ 3.5 is a medical emergency (arrhythmia, coma, AKI). Aggressive IV fluids, IV bisphosphonate, consider calcitonin for rapid effect, denosumab if bisphosphonate-refractory; ECG monitoring."}], "src": "Payne RB et al. BMJ 1973 (0.02 mmol/L per g/L albumin below 40); NICE CKS Hypercalcaemia 2024; Society for Endocrinology Emergency Guidance (acute hypocalcaemia 2016; hypercalcaemia 2016)", "note": "The Payne correction is unreliable at extremes of albumin, in critical illness, CKD, acid–base disturbance and with paraproteins — measure ionised calcium (blood gas) when it matters. Some UK labs use locally derived correction factors (e.g. 0.016–0.025); always use the lab's adjusted value if reported."}, {"id": "egfr-ckdepi-2021", "name": "eGFR — CKD-EPI 2021 (creatinine, race-free)", "kind": "formula", "group": "General", "use": "Estimate glomerular filtration rate from serum creatinine, age and sex to stage chronic kidney disease and dose renally cleared drugs (CKD-EPI 2021 refit without race).", "inputs": [{"k": "cr", "label": "Serum creatinine", "unit": "µmol/L", "min": 20, "max": 2000, "step": 1}, {"k": "age", "label": "Age", "unit": "years", "min": 18, "max": 110, "step": 1}, {"k": "sex", "label": "Sex (0 = male, 1 = female)", "unit": "", "min": 0, "max": 1, "step": 1, "opts": [["Male", 0], ["Female", 1]]}], "expr": "142 * pow(min(cr / 88.4 / (0.9 - 0.2 * sex), 1), (-0.302 + 0.061 * sex)) * pow(max(cr / 88.4 / (0.9 - 0.2 * sex), 1), -1.2) * pow(0.9938, age) * (1 + 0.012 * sex)", "unit": "mL/min/1.73 m²", "bands": [{"min": 0, "max": 14.9, "label": "G5 — kidney failure", "text": "eGFR < 15: kidney failure (CKD stage 5). Renal replacement therapy planning; nephrology care."}, {"min": 15, "max": 29.9, "label": "G4 — severely decreased", "text": "eGFR 15–29: refer to nephrology (NICE NG203). Review drug doses (metformin contraindicated < 30, DOAC and many antibiotic dose reductions)."}, {"min": 30, "max": 44.9, "label": "G3b — moderately to severely decreased", "text": "eGFR 30–44: CKD stage 3b. Check ACR; annual monitoring at minimum; adjust renally cleared drugs; consider SGLT2 inhibitor if albuminuria or diabetes."}, {"min": 45, "max": 59.9, "label": "G3a — mildly to moderately decreased", "text": "eGFR 45–59: CKD stage 3a if sustained > 3 months. Check ACR, BP, HbA1c, lipids; cardiovascular risk management."}, {"min": 60, "max": 89.9, "label": "G2 — mildly decreased", "text": "eGFR 60–89: only CKD if there is other evidence of kidney damage (ACR ≥ 3 mg/mmol, haematuria, structural abnormality). Normal for many older adults."}, {"min": 90, "max": 250, "label": "G1 — normal or high", "text": "eGFR ≥ 90: normal. CKD only if markers of kidney damage are present. Hyperfiltration can occur in early diabetes."}], "src": "Inker LA et al. New creatinine- and cystatin C-based equations to estimate GFR without race. NEJM 2021; NICE NG203 Chronic kidney disease 2021 (updated 2025 — adopts CKD-EPI 2021 without ethnicity adjustment); KDIGO 2024 CKD guideline", "note": "Formula: 142 × min(Scr/κ, 1)^α × max(Scr/κ, 1)^−1.200 × 0.9938^age × 1.012 [if female]; κ = 0.7 (F) / 0.9 (M), α = −0.241 (F) / −0.302 (M); Scr in mg/dL = µmol/L ÷ 88.4. NOT valid in AKI (creatinine not at steady state), pregnancy, extremes of muscle mass (amputees, body-builders, cachexia, spinal injury), under 18 (use Schwartz) or with creatinine-affecting drugs (trimethoprim, cimetidine). For drug dosing, many SmPCs still specify Cockcroft–Gault creatinine clearance (uses actual weight, not indexed to 1.73 m²). Add cystatin C (CKD-EPI 2021 cr-cys) where eGFR accuracy is critical. The 'sex' input is numeric 0/1; an 'opts' array is included for UIs that render a selector."}, {"id": "bmi", "name": "Body mass index", "kind": "formula", "group": "General", "use": "Classify weight status in adults from height and weight (kg/m²).", "inputs": [{"k": "wt", "label": "Weight", "unit": "kg", "min": 20, "max": 350, "step": 0.1}, {"k": "ht", "label": "Height", "unit": "cm", "min": 100, "max": 250, "step": 0.5}], "expr": "wt / pow(ht / 100, 2)", "unit": "kg/m²", "bands": [{"min": 0, "max": 18.49, "label": "Underweight", "text": "BMI < 18.5. Assess for malnutrition, eating disorder, malabsorption, malignancy, chronic disease; consider MUST screening and dietetic referral."}, {"min": 18.5, "max": 24.9, "label": "Healthy weight", "text": "BMI 18.5–24.9. For people of South Asian, Chinese, other Asian, Middle Eastern, Black African or African-Caribbean background, NICE NG246 lowers the overweight threshold to 23 and obesity to 27.5 kg/m²."}, {"min": 25, "max": 29.9, "label": "Overweight", "text": "BMI 25–29.9. Measure waist-to-height ratio (> 0.5 = increased central adiposity, NICE NG246 2025); lifestyle intervention; check cardiometabolic risk."}, {"min": 30, "max": 34.9, "label": "Obesity class I", "text": "BMI 30–34.9. Offer weight-management programme; consider pharmacotherapy (GLP-1/GIP agonists per NICE TA) with comorbidity; screen for T2DM, hypertension, dyslipidaemia, OSA."}, {"min": 35, "max": 39.9, "label": "Obesity class II", "text": "BMI 35–39.9. Consider referral to specialist weight management (tier 3); bariatric surgery assessment if comorbidity (NICE NG246)."}, {"min": 40, "max": 150, "label": "Obesity class III", "text": "BMI ≥ 40. Consider bariatric surgery assessment; higher perioperative and anaesthetic risk; adjust drug dosing (ideal/adjusted body weight)."}], "src": "WHO 2000 classification; NICE NG246 Overweight and obesity management 2025 (replaces CG189; ethnicity-specific thresholds, waist-to-height ratio)", "note": "BMI does not distinguish muscle from fat and misclassifies athletes, the elderly (sarcopenia), pregnant women and those with oedema/ascites. Use age- and sex-specific centiles (UK-WHO/RCPCH charts) in children. Interpret alongside waist-to-height ratio and comorbidity."}, {"id": "ibw-devine", "name": "Ideal body weight (Devine)", "kind": "formula", "group": "General", "use": "Estimate ideal body weight for drug dosing (aminoglycosides, tidal-volume calculation in ARDS, some chemotherapy) and for adjusted body weight.", "inputs": [{"k": "ht", "label": "Height", "unit": "cm", "min": 120, "max": 230, "step": 0.5}, {"k": "sex", "label": "Sex (0 = male, 1 = female)", "unit": "", "min": 0, "max": 1, "step": 1, "opts": [["Male", 0], ["Female", 1]]}], "expr": "(50 - 4.5 * sex) + 2.3 * (ht - 152.4) / 2.54", "unit": "kg", "bands": [{"min": 0, "max": 300, "label": "Ideal body weight", "text": "Male: 50 kg + 2.3 kg per inch over 5 ft (152.4 cm). Female: 45.5 kg + 2.3 kg per inch over 5 ft. Lung-protective ventilation: 6 mL/kg of this (predicted) body weight. Adjusted body weight for obese patients = IBW + 0.4 × (actual − IBW)."}], "src": "Devine BJ. Drug Intell Clin Pharm 1974; ARDSNet (Brower RG et al. NEJM 2000) uses the near-identical predicted body weight: 50 + 0.91 × (cm − 152.4) for men, 45.5 + 0.91 × (cm − 152.4) for women", "note": "Never validated for health outcomes — it is a dosing convention. Inaccurate below 152 cm (gives negative adjustment); some sources use a minimum of 45–50 kg. ARDSNet's 'predicted body weight' uses 0.91 kg/cm, which differs from Devine by < 1 kg. For drug dosing follow the SmPC's specified weight (actual, ideal or adjusted)."}, {"id": "qtc-bazett", "name": "QTc — Bazett", "kind": "formula", "group": "Cardiac", "use": "Correct the QT interval for heart rate (QTc = QT / √RR); the most widely used formula and the one most drug-safety thresholds were derived with, but it over-corrects at tachycardia and under-corrects at bradycardia.", "inputs": [{"k": "qt", "label": "QT interval (measured, lead II or V5, longest; use tangent method)", "unit": "ms", "min": 200, "max": 800, "step": 1}, {"k": "hr", "label": "Heart rate", "unit": "/min", "min": 20, "max": 220, "step": 1}], "expr": "qt / sqrt(60 / hr)", "unit": "ms", "bands": [{"min": 0, "max": 349, "label": "Short QT", "text": "QTc < 350 ms (some use < 340–360): consider short QT syndrome if recurrent syncope, AF at a young age or family history of sudden death; hypercalcaemia, digoxin."}, {"min": 350, "max": 450, "label": "Normal", "text": "Normal QTc: ≤ 450 ms in men, ≤ 460 ms in women (AHA/ACC/HRS 2009). Values 440–450 are borderline in some references."}, {"min": 451, "max": 470, "label": "Borderline / prolonged in women", "text": "451–460 ms is borderline in men and normal in women; > 460 ms is prolonged in women. Review QT-prolonging drugs (crediblemeds.org), electrolytes (K⁺, Mg²⁺, Ca²⁺), repeat ECG."}, {"min": 471, "max": 499, "label": "Prolonged", "text": "QTc > 470 ms (men) / > 480 ms (women) is clearly prolonged (ESC 2022: ≥ 480 ms suggests LQTS). Stop/avoid QT-prolonging drugs, correct electrolytes, consider cardiology review and family history (congenital LQTS)."}, {"min": 500, "max": 1000, "label": "Markedly prolonged — high torsades risk", "text": "QTc ≥ 500 ms: substantial risk of torsades de pointes. Stop all QT-prolonging drugs, continuous monitoring, correct K⁺ to > 4.0 and Mg²⁺ to > 1.0 mmol/L, IV magnesium 2 g if torsades; avoid bradycardia (consider isoprenaline/overdrive pacing)."}], "src": "Bazett HC. Heart 1920; Rautaharju PM et al. AHA/ACCF/HRS recommendations, Circulation 2009; ESC 2022 ventricular arrhythmia guideline", "note": "RR interval (s) = 60 / HR. Bazett is unreliable outside HR 60–100: at HR > 100 it over-estimates QTc (consider Fridericia or Framingham); at HR < 60 it under-estimates. In AF, average several beats. In bundle branch block (QRS > 120 ms) use JT interval or modified QT (QT − (QRS − 120)). Measure QT from the start of the QRS to the end of the T wave (tangent of the steepest downslope), excluding U waves."}, {"id": "qtc-fridericia", "name": "QTc — Fridericia", "kind": "formula", "group": "Cardiac", "use": "Cube-root heart-rate correction of the QT interval (QTc = QT / ∛RR); more accurate than Bazett at heart rates above 100 or below 60 and preferred by many regulators and drug-safety guidance.", "inputs": [{"k": "qt", "label": "QT interval (measured, lead II or V5, longest; tangent method)", "unit": "ms", "min": 200, "max": 800, "step": 1}, {"k": "hr", "label": "Heart rate", "unit": "/min", "min": 20, "max": 220, "step": 1}], "expr": "qt / pow(60 / hr, 1 / 3)", "unit": "ms", "bands": [{"min": 0, "max": 349, "label": "Short QT", "text": "QTc < 350 ms: consider short QT syndrome if syncope, early AF or family history of sudden death; hypercalcaemia, digoxin."}, {"min": 350, "max": 450, "label": "Normal", "text": "Normal QTc: ≤ 450 ms in men, ≤ 460 ms in women."}, {"min": 451, "max": 470, "label": "Borderline / prolonged in women", "text": "451–460 borderline in men, normal in women; > 460 prolonged in women. Review QT-prolonging drugs and electrolytes; repeat ECG."}, {"min": 471, "max": 499, "label": "Prolonged", "text": "Clearly prolonged (> 470 men, > 480 women; ESC 2022 ≥ 480 suggests LQTS). Stop/avoid QT-prolonging drugs, correct K⁺/Mg²⁺/Ca²⁺, cardiology review."}, {"min": 500, "max": 1000, "label": "Markedly prolonged — high torsades risk", "text": "QTc ≥ 500 ms: high torsades risk. Stop all QT-prolonging drugs, continuous monitoring, K⁺ > 4.0 and Mg²⁺ > 1.0 mmol/L, IV magnesium 2 g for torsades, avoid bradycardia."}], "src": "Fridericia LS. Acta Med Scand 1920; Vandenberk B et al. J Am Heart Assoc 2016 (Fridericia and Framingham best for mortality prediction); FDA/ICH E14 guidance favours Fridericia", "note": "RR (s) = 60 / HR. Fridericia is the preferred formula at HR > 100 (e.g. sepsis, methadone/antipsychotic monitoring) and in clinical trials; Bazett remains standard in many UK drug-monitoring protocols, so state which formula you used. Same measurement caveats as Bazett (tangent method, exclude U wave, BBB adjustment, average beats in AF)."}, {"id": "holliday-segar", "name": "Maintenance fluids — Holliday–Segar (4-2-1)", "kind": "formula", "group": "General", "use": "Estimate 24-hour maintenance fluid requirement by weight, mainly in children; the 4-2-1 rule gives the equivalent hourly rate.", "inputs": [{"k": "wt", "label": "Weight", "unit": "kg", "min": 2, "max": 150, "step": 0.1}], "expr": "100 * min(wt, 10) + 50 * max(min(wt - 10, 10), 0) + 20 * max(wt - 20, 0)", "unit": "mL per 24 h", "bands": [{"min": 0, "max": 1000, "label": "≤ 10 kg", "text": "100 mL/kg/day (4 mL/kg/h). Divide by 24 for the hourly rate. Children: use isotonic fluid with glucose (e.g. 0.9% NaCl + 5% glucose ± KCl 20 mmol/L); in acute illness consider restricting to 50–80% of maintenance because of ADH excess (NICE NG29)."}, {"min": 1001, "max": 1500, "label": "10–20 kg", "text": "1000 mL + 50 mL/kg/day for each kg over 10 (40 mL/h + 2 mL/kg/h over 10). Divide by 24 for the hourly rate. Isotonic fluids only in children (NICE NG29); weigh daily and check U&E at least every 24 h."}, {"min": 1501, "max": 10000, "label": "> 20 kg", "text": "1500 mL + 20 mL/kg/day for each kg over 20 (60 mL/h + 1 mL/kg/h over 20), typically capped at ~2400–2500 mL/day. In ADULTS, NICE CG174 recommends 25–30 mL/kg/day water, 1 mmol/kg/day Na⁺/K⁺/Cl⁻ and 50–100 g/day glucose — Holliday–Segar over-estimates adult needs, especially in the elderly, obese or those with heart/renal failure."}], "src": "Holliday MA, Segar WE. Pediatrics 1957; NICE NG29 IV fluid therapy in children and young people 2015 (updated 2020); NICE CG174 IV fluid therapy in adults 2013 (updated 2017)", "note": "This is MAINTENANCE only — add replacement of deficit and ongoing losses separately. Derived from caloric expenditure of healthy children in 1957; sick children often need less (SIADH), and neonates in the first week use day-of-life-based regimens (60–150 mL/kg/day). Hypotonic maintenance fluids (0.18% or 0.45% NaCl) are no longer used in children because of hyponatraemic encephalopathy."}, {"id": "age-adjusted-ddimer", "name": "Age-adjusted D-dimer threshold", "kind": "formula", "group": "Respiratory", "use": "Raise the D-dimer cut-off in patients over 50 with a 'PE unlikely' (or 'DVT unlikely') Wells score to reduce unnecessary imaging without loss of safety.", "inputs": [{"k": "age", "label": "Age", "unit": "years", "min": 18, "max": 110, "step": 1}], "expr": "max(age, 50) * 10", "unit": "µg/L FEU (= ng/mL FEU)", "bands": [{"min": 0, "max": 500, "label": "Standard threshold (age ≤ 50)", "text": "Cut-off 500 µg/L FEU. D-dimer below this in a Wells 'unlikely' patient excludes VTE."}, {"min": 501, "max": 1200, "label": "Age-adjusted threshold (age > 50)", "text": "Cut-off = age × 10 µg/L FEU (e.g. 75 years → 750). D-dimer below this in a Wells 'PE unlikely' / 'DVT unlikely' patient excludes VTE (ADJUST-PE: 3-month VTE 0.3% in those excluded by age-adjusted threshold alone). Above → imaging."}], "src": "Righini M et al. ADJUST-PE, JAMA 2014; Schouten HJ et al. BMJ 2013 (meta-analysis); NICE NG158 2020 (consider age-adjusted D-dimer); ESC 2019 PE guideline (Class IIa)", "note": "Only valid for assays reporting in fibrinogen-equivalent units (FEU) with a standard cut-off of 500 µg/L (or 0.5 mg/L). For D-dimer-unit (DDU) assays with a 250 cut-off, use age × 5. Not validated for YEARS (which uses 500/1000 thresholds) or for 'PE likely' patients, in whom D-dimer should not be used at all. Check your lab's units: mg/L FEU × 1000 = µg/L FEU."}, {"id": "abi", "name": "Ankle–brachial index (ABPI)", "kind": "formula", "group": "Cardiac", "use": "Diagnose and grade peripheral arterial disease from Doppler ankle and brachial systolic pressures; also required before compression bandaging of leg ulcers.", "inputs": [{"k": "ankle", "label": "Highest ankle systolic pressure (dorsalis pedis or posterior tibial) on the tested leg", "unit": "mmHg", "min": 0, "max": 300, "step": 1}, {"k": "arm", "label": "Highest brachial systolic pressure (of both arms)", "unit": "mmHg", "min": 50, "max": 300, "step": 1}], "expr": "ankle / arm", "unit": "", "bands": [{"min": 0, "max": 0.4, "label": "Severe PAD / critical limb ischaemia", "text": "ABPI ≤ 0.40: severe arterial insufficiency; rest pain, ulceration or gangrene likely (chronic limb-threatening ischaemia). Urgent vascular referral. Compression contraindicated."}, {"min": 0.41, "max": 0.9, "label": "Peripheral arterial disease", "text": "ABPI ≤ 0.90 is diagnostic of PAD (sensitivity ~75%, specificity ~95%). 0.5–0.9: intermittent claudication range — supervised exercise, antiplatelet, statin, BP and glycaemic control, smoking cessation (NICE CG147). ABPI < 0.8: compression bandaging unsafe without vascular advice; 0.8–0.9 reduced compression only."}, {"min": 0.91, "max": 0.99, "label": "Borderline", "text": "ABPI 0.91–0.99: borderline. If symptoms suggest PAD, perform post-exercise ABPI (a fall of > 20% or ankle pressure drop > 30 mmHg is diagnostic) or toe-brachial index."}, {"min": 1.0, "max": 1.4, "label": "Normal", "text": "ABPI 1.00–1.40: normal. Does not exclude PAD in diabetics or the elderly with calcified vessels — use toe-brachial index (< 0.7 abnormal) if clinical suspicion persists."}, {"min": 1.41, "max": 5, "label": "Non-compressible (calcified) arteries", "text": "ABPI > 1.40: medial arterial calcification (diabetes, CKD, elderly) makes the result uninterpretable and is itself associated with increased cardiovascular risk. Use toe-brachial index, Doppler waveform analysis or duplex ultrasound."}], "src": "Aboyans V et al. AHA scientific statement on ABI measurement and interpretation, Circulation 2012; ESC/ESVS 2024 peripheral arterial and aortic diseases guideline; NICE CG147 Peripheral arterial disease 2012 (updated 2020)", "note": "Technique: patient supine 5–10 min, appropriately sized cuff just above the malleoli, 8 MHz hand-held Doppler; record both DP and PT, use the higher for the numerator and the higher of the two brachial pressures for the denominator. Calculate each leg separately. Not reliable in acute limb ischaemia (clinical diagnosis) or when ankle oedema prevents cuff inflation."}, {"id": "post-test-probability", "name": "Post-test probability from a likelihood ratio", "kind": "formula", "group": "General", "use": "Convert a pre-test probability and a test's likelihood ratio (positive or negative) into a post-test probability using Bayes' theorem — the core of evidence-based bedside diagnosis.", "inputs": [{"k": "pre", "label": "Pre-test probability", "unit": "%", "min": 0.1, "max": 99.9, "step": 0.1}, {"k": "lr", "label": "Likelihood ratio (LR+ for a positive result, LR− for a negative result)", "unit": "", "min": 0.001, "max": 1000, "step": 0.01}], "expr": "100 * (pre / (100 - pre)) * lr / (1 + (pre / (100 - pre)) * lr)", "unit": "% post-test probability", "bands": [{"min": 0, "max": 2, "label": "Very low — disease effectively excluded", "text": "Post-test probability ≤ 2%: below the typical 'test threshold' for most serious diagnoses (e.g. PE is considered excluded below ~2%). Stop testing unless the consequence of a miss is catastrophic."}, {"min": 2.01, "max": 20, "label": "Low", "text": "Disease unlikely but not excluded. Further testing is worthwhile if a test with a strong LR− (< 0.1) is available; otherwise observe and safety-net."}, {"min": 20.01, "max": 70, "label": "Intermediate — keep testing", "text": "Between the test and treatment thresholds: this is where further investigation changes management most. Choose the test with the greatest shift (LR+ > 10 or LR− < 0.1)."}, {"min": 70.01, "max": 95, "label": "High", "text": "Disease likely; often above the treatment threshold. Confirm if the treatment is risky or expensive; otherwise treat."}, {"min": 95.01, "max": 100, "label": "Very high — effectively confirmed", "text": "Post-test probability > 95%: treat. Further testing is unlikely to change management and a negative result would more likely be a false negative."}], "src": "Bayes' theorem; Sackett DL et al. Clinical Epidemiology 1991; McGee S. Evidence-Based Physical Diagnosis, 5th ed. 2022 (bedside LRs); Fagan TJ. NEJM 1975 (nomogram)", "note": "Pre-test odds = p / (1 − p); post-test odds = pre-test odds × LR; post-test probability = odds / (1 + odds). Rule of thumb (McGee): LR 2 / 5 / 10 raise probability by ~15 / 30 / 45 percentage points; LR 0.5 / 0.2 / 0.1 lower it by ~15 / 30 / 45. LRs of 0.5–2 barely change probability. Multiply LRs of independent findings in series, but most bedside findings are not independent, so be cautious combining more than two or three. Pre-test probability should come from a validated score or local prevalence, not a guess."}];
